"""손으로 확인한 회사별 변곡점 원인(뉴스 원문을 읽고 확인한 것만, 출처 필수).

자동 해설은 숫자·리포트 제목·뉴스 제목으로 원인을 추정한다. 여기에 적은 내용은 기사 본문으로 확인한 사실이라
해당 시기 카드의 맨 앞에 '확인된 원인'으로 붙고, 핵심 요인 요약에서도 가장 먼저 쓰인다.

N(code, 날짜, 방향, 요인, 제목, 설명, 출처 URL, 매체)
  방향: '+' 주가 상승 요인, '-' 하락 요인
  요인: earn(실적: 분기 실적 발표·시장 기대 대비) cycle(업황) trend(트렌드) news(뉴스) val(밸류에이션) cat(촉매제: IR·테마·공시·주주환원) macro(거시·시장)
새로 확인한 원인은 한 줄씩 추가하면 다음 실행 때 해당 시기 카드에 반영된다.
"""

NOTES = []


def N(code, d, dir_, cat, title, text, url="", office=""):
    if any(n["code"] == code and n["d"] == d and n["dir"] == dir_ for n in NOTES):
        return  # 업종이 겹치는 회사의 같은 사건 중복 방지
    NOTES.append({"code": code, "d": d, "dir": dir_, "cat": cat, "title": title, "text": text, "url": url, "office": office})


