  "2분기 매출 2,653억원(+46%), 영업이익 522억원(+34%)으로 성장은 이어졌지만 영업이익이 시장 기대치를 9.2% 밑돌았어요. 미국 관세 대응으로 항공 특송이 늘어 운반비 비중이 2.3%→2.9%로 올랐고 인건비도 36% 늘었어요. "
