  "2024년 4분기 매출은 5,580억원으로 27.8%, 영업이익은 398억원으로 76.8% 늘어 시장 기대를 각각 8.0%, 3.9% 웃돌았어요. 발표 뒤 주가는 8% 오른 16만6,000원에 마감했고, 한국투자증권(20만→23만원) 등 6개 증권사가 목표가를 올렸어요. 역대 최대 실적이 2022년 10월부터 이어진 +510% 상승 국면 후반부를 밀어 올렸어요.",
