# ---- 클리오(237880)
N("237880", "2024-02-18", "+", "earn", "4분기 영업익 116억 +123%, 11개 분기 연속 최대 매출",
  "클리오는 2023년 4분기 연결 매출 897억원(+23.9%), 영업이익 116억원(+123%)을 거뒀고 11개 분기 연속 매출이 직전 기록을 넘었어요. 2023년 연간으로는 매출 3306억원, 영업이익 338억원이었고 해외 매출 비중이 44%까지 올라왔어요. 분기마다 이어진 최대 실적 행진이 2022년 말부터 이어진 상승 국면을 떠받친 핵심 근거였어요.",
  "https://v.daum.net/v/20240218091916592", "머니투데이")
# ---- 코스메카코리아(241710)
N("241710", "2024-01-08", "+", "earn", "4분기 영업익 149억 전망, 컨센서스 137억 상회…목표가 5.6만",
  "하나증권은 코스메카코리아의 2023년 4분기 매출을 약 1200억원(+12%), 영업이익을 약 149억원(+295%)으로 추정해 컨센서스 약 137억원을 넘을 것으로 봤어요. 2023년 연간 영업이익은 약 490억원(+372%)으로 추정하며 목표가를 5만2000원에서 5만6000원으로 올렸어요. 인디 브랜드 수주와 미국 법인의 OTC 역량이 실적 급증을 이끌며 1300% 넘는 상승 국면의 근거가 됐어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/41280", "스마트투데이")
# ---- 한국비엔씨(256840)
N("256840", "2024-02-29", "+", "cat", "GLP-1 비만치료제 공동개발 발표에 장중 +13.9%, 52주 신고가",
  "한국비엔씨는 2024년 2월 29일 장 초반 전일 대비 13.94% 오른 5190원에 거래되며 2023년 9월의 52주 최고가 4860원을 넘어섰어요. 프로앱텍과 당뇨·비만 치료용 GLP-1 작용제를 공동 개발한다는 발표에 미국 바이오 기업의 비만 치료제 임상 호재가 겹쳐 비만 치료제 테마로 묶였어요. 2023년 10월 이후 상승 국면의 막바지 고점을 만든 테마성 재료였어요.",
  "https://core.asiae.co.kr/article/2024022909412396221", "아시아경제")
# ---- 펌텍코리아(251970)
N("251970", "2024-05-08", "+", "earn", "1분기 영업익 102억, 컨센서스 95억 상회",
  "펌텍코리아는 2024년 1분기 매출 769억원, 영업이익 102억원을 내 시장 컨센서스 영업이익 95억원을 약 7% 웃돌았어요. 중소형 인디 브랜드향 매출이 전년 대비 27% 늘었고 펌프 용기(+38%)·콤팩트(+28%)가 성장을 이끌었어요. 한화투자증권은 목표가 3만8000원과 매수 의견을 유지했고(직전 종가 2만7350원), 인디 브랜드 수혜가 실적으로 확인되며 상승 국면을 이어간 근거가 됐어요.",
  "https://core.asiae.co.kr/article/2024050808065972984", "아시아경제")
# ---- 씨티케이(260930)
N("260930", "2025-07-11", "+", "cat", "미국 OTC 공장 인수·친환경 플라스틱…2025년 영업익 20억 +1397% 전망",
  "키움증권은 씨티케이가 2025년 3월 자회사를 통해 미국 OTC 제조 공장을 인수해 선케어 제품 개발과 미국 진출 한국 기업 대상 OTC 솔루션 공급에 나선다고 짚었어요. 2025년 매출은 983억원(+18%), 영업이익은 20억원(+1397%)으로 전망했고 현지 생산이 관세·물류비 대응에 유리하다고 봤어요. 미국 OTC 진출이 기업가치 재평가 논리로 제시되며 2025년 3~8월 반등 국면의 재료가 됐어요.",
  "https://view.asiae.co.kr/article/2025071107491153685", "아시아경제")
# ---- 원텍(336570)
N("336570", "2024-05-13", "-", "earn", "1분기 영업익 66억, 컨센서스 135억 대비 -51% 어닝쇼크…목표가 1.5만→1.2만",
  "원텍은 2024년 1분기 연결 매출 226억원(-20.7%), 영업이익 66억원(-50.7%)으로 시장 예상치(매출 331억원, 영업이익 135억원)를 각각 약 32%, 51% 밑돌았어요. 해외 자회사와 모회사의 매출 인식 시점 차이(약 49억5000만원)에 국내 RF 장비와 브라질 자회사 판매 감소가 겹쳤어요. 한국투자증권은 목표가를 1만5000원에서 1만2000원으로 낮췄고, 실적 신뢰도 하락이 2023년 8월 이후 하락 국면을 깊게 만든 계기가 됐어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/50103", "스마트투데이")
# ---- 티앤엘(340570)
N("340570", "2024-04-11", "+", "cat", "유안타 신규 매수·목표가 10만원, '상반기 사상 최대 실적' 전망",
  "유안타증권은 티앤엘에 대해 매수 의견과 목표가 10만원으로 커버리지를 시작했어요. 매출의 62%를 차지하는 고객사 HERO가 2022년 처치앤드와이트에 인수된 뒤 2023년 판매처가 204% 늘었는데도 모회사 유통망의 15~20%에 그쳐 확장 여지가 크다고 봤고, 미국 재입고와 신규 국가 진출로 2분기 사상 최대 매출을 예상했어요. 패치형 트러블케어 수출 확대 기대가 2022년부터 이어진 상승 국면의 핵심 논리였어요.",
  "https://www.asiae.co.kr/en/article/2024041108185927898", "아시아경제")
# ---- 씨앤씨인터내셔널(352480)
N("352480", "2024-02-27", "+", "earn", "4분기 매출 631억 +64% 사상 최대, 목표가 8만→8.8만",
  "씨앤씨인터내셔널은 2023년 4분기 연결 매출 631억원(+64%)으로 분기 최대를 기록해 컨센서스를 4% 웃돌았고, 영업이익은 91억원(+95%)으로 연말 성과급 23억원 탓에 컨센서스를 15% 밑돌았어요. KB증권은 2024년 매출 2807억원(+27%), 영업이익 449억원(+40%)을 전망하며 2024~2026년 영업이익 추정치를 10% 안팎 올리고 목표가를 8만원에서 8만8000원으로 높였어요. 고객사 확대에 따른 외형 고성장 확인이 750% 넘는 상승 국면을 이어가게 한 근거였어요.",
  "https://www.asiae.co.kr/en/article/2024022707510892636", "아시아경제")
N("340570", "2025-09-17", "-", "earn", "2분기 영업익 100억 -52%, 하이드로콜로이드 수출 -37.8%…목표가 8만으로 하향",
  "티앤엘은 2025년 2분기 매출 388억원(-29.3%), 영업이익 100억원(-52.0%)으로 급감했고 주력인 하이드로콜로이드 창상피복재 수출이 232억원으로 37.8% 줄었어요. 상상인증권은 관세와 미국 소비 둔화로 2분기부터 성장이 꺾였고 3~4분기도 비슷할 것으로 보며 목표가를 8만원으로 낮췄어요. 미국 수출 둔화가 실적으로 확인되며 2025년 1~10월 하락 국면을 뒷받침한 사건이었어요.",
  "https://core.asiae.co.kr/article/2025091707505545855", "아시아경제")
# ---- 마녀공장(439090)
N("439090", "2024-06-12", "-", "news", "상장 1년 주가 -45.9%, 2023년 영업익 -35%·최대주주 246만주 블록딜",
  "마녀공장은 '따상'으로 상장해 4만1600원을 찍었지만 2024년 6월 7일 종가 2만2500원으로 1년 새 45.91% 내렸어요. 2023년 매출은 1050억원(+3.1%)에 그친 반면 영업이익은 159억원(-35.1%)으로 줄며 영업이익률이 15.1%까지 낮아졌고, 최대주주 엘앤피코스메틱 측이 2024년 1~5월 약 246만주를 팔아 지분율이 66.86%에서 51.87%로 내려갔어요. 이익률 하락과 최대주주 물량 출회가 겹친 것이 2023년 8월 이후 하락 국면의 핵심 원인이었어요.",
  "https://www.newstomato.com/ReadNews.aspx?no=1232359", "IB토마토")
N("336570", "2023-08-05", "+", "news", "올해만 주가 3배…올리지오 소모품 모델로 실적 개선 사이클 초입",
  "원텍 주가는 2023년 들어 약 3배로 올랐고, 삼성증권은 비침습 미용 시술 수요 증가와 함께 원텍의 실적 개선 사이클이 이제 시작 단계라고 평가했어요. 2020년 국내 출시한 RF 장비 올리지오로 장비 판매 뒤 소모품 매출이 쌓이는 클래시스식 모델을 따라가고 있고, 대만 출시와 브라질·중국 인허가가 연내 기대됐어요. 소모품 기반 이익률 상승 기대가 2022년 9월부터 이어진 500% 넘는 급등 국면의 논리였어요.",
  "https://www.mt.co.kr/stock/2023/08/05/2023080418283097441", "머니투데이")
# ---- 바이오에프디엔씨(251120)
N("251120", "2024-10-10", "+", "news", "마이크로니들 패치·식물세포 PDRN으로 성장동력…장중 +2.5%",
  "바이오에프디엔씨는 2024년 10월 10일 장중 전일 대비 2.47% 오른 1만5750원에 거래됐어요. NH투자증권은 EGF·FGF 중심으로 매출 성장이 이어지는 가운데 마이크로니들 패치 생산설비를 갖추고 식물세포 유래 고순도 PDRN 생산 기술을 확보해 성장동력을 마련했다고 분석했어요. PDRN·스킨부스터 원료 기대가 2023년 10월 이후 반등 국면을 떠받친 재료였어요.",
  "https://core.asiae.co.kr/article/2024101011040558300", "아시아경제")
# ---- 엘앤씨바이오(290650)
N("290650", "2023-05-15", "+", "earn", "1분기 매출 148억 +34.5% 상장 후 1분기 최대, 메가카티 하반기 출시 준비",
  "엘앤씨바이오는 2023년 1분기 연결 매출 약 147억9000만원(+34.5%)으로 2018년 상장 이후 1분기 최대 매출을 냈고 영업이익은 약 21억2000만원(+4.5%)이었어요. 회사는 퇴행성 관절염 치료용 연골 재생 의료기기 메가카티가 하반기 계획대로 출시되면 연간 매출과 영업이익이 역대 최대가 될 것이라고 밝혔어요. 실적 성장에 메가카티 출시 기대가 더해진 것이 2023년 상반기 상승 국면의 동력이었어요.",
  "https://dailymedi.com/news/news_view.php?wr_id=897696", "데일리메디")
# ---- 잉글우드랩(950140)
N("950140", "2024-05-20", "+", "earn", "1분기 영업익 66억 +19.2%, 미국 선케어 OTC 수혜로 두 달새 +40%",
  "잉글우드랩은 2024년 1분기 매출 526억원(+14.2%), 영업이익 66억원(+19.2%)을 냈고 주가는 3월부터 약 두 달 동안 40%가량 올랐어요. 미국에서 선크림은 OTC 의약품으로 분류돼 FDA 요건 충족에 약 2년이 걸리는데, OTC 제조 허가를 가진 잉글우드랩이 인디 브랜드의 선케어 확장 수혜를 받는다는 분석이에요. FS리서치는 2024년 매출 +27%, 영업이익 +38%를 전망했고, 미국 선케어 OTC 역량이 500% 넘는 상승 국면의 핵심 논리였어요.",
  "https://core.asiae.co.kr/article/2024051715454839643", "아시아경제")
N("950140", "2026-08-10", "-", "earn", "2분기 매출 519억 -9.7%, 영업익 87억 -13.2% 역성장",
  "잉글우드랩은 2026년 2분기 잠정 매출 519억3000만원(-9.7%), 영업이익 87억4000만원(-13.2%)으로 매출과 이익이 함께 줄었다고 공시했어요. 순이익은 67억원으로 129.5% 늘었지만 본업 실적은 역성장했어요. 미국 선케어 OTC 성장주로 받던 기대가 실적 감소로 꺾인 것이 2025년 7월 이후 하락 국면을 확인시킨 사건이었어요.",
  "https://mbiz.heraldcorp.com/article/10836277", "헤럴드경제")

