N("005300", "2024-10-29", "-", "news", "3분기 영업익 780억(-7%) 기대 하회 전망, 9월 52주 신저가 11만6000원",
  "교보증권은 롯데칠성의 3분기 연결 매출이 1조973억원(+32%)으로 늘겠지만 영업이익은 780억원으로 7% 줄어 시장 기대를 밑돌 것으로 봤어요. 주가는 8월 2일 14만5500원에서 9월 25일 장중 11만6000원으로 52주 최저가를 찍었고, 국민연금은 지분을 11.58%에서 9.18%로 줄였어요. 외형 성장에도 이익이 뒷걸음질한 것이 2022년부터 이어진 하락 국면을 연장시켰어요.",
  "https://www.sidae.com/article/2024102809353080929", "시대")
