N("003920", "2025-10-28", "-", "news", "5월 고점 8만3800원 대비 6개월 새 -34%, 상반기 매출 -6.4%",
  "남양유업 주가는 2025년 5월 9일 8만3800원에서 10월 28일 5만4700원으로 6개월 만에 34% 넘게 떨어졌는데, 같은 기간 코스피는 약 57% 올랐어요. 2024년 3분기부터 4분기 연속 영업흑자를 냈지만 광고비·판관비 절감에 기댄 것이었고, 2025년 상반기 매출은 4477억원으로 6.4%(수출 -38%) 줄었어요. 성장 전략 부재와 우선주 소외 논란이 한앤코 인수 후 기대를 꺾은 하락 국면의 배경이었어요.",
  "https://news.tf.co.kr/read/economy/2256347.htm", "더팩트")
# ---- 한성기업(003680) 급등 후 하락 국면
N("003680", "2026-07-18", "-", "cat", "8거래일 +213% 뒤 매매정지, 실적 반토막 테마주 경고",
  "한성기업 주가는 7월 6일 4230원에서 상한가(9·10일)와 13~15일 연속 급등(+9.93%, +20.11%, +29.99%)을 거치며 8거래일 만에 약 213% 올랐고, 7월 16일 하루 매매거래가 정지됐어요. 반면 2025년 매출은 3184억원(-4.2%), 영업이익은 58억원(약 -47%)으로 영업이익률이 1.83%에 그쳐 전문가들은 실적이 뒷받침되지 않는 급등이라고 경고했어요. 상폐 회피 '애국 테마' 매수가 정점을 찍고 거래정지가 나온 이 시점이 이후 하락 국면의 출발점이에요.",
  "https://www.hankyung.com/article/202607171441i", "한국경제")
# ---- 농심(004370)
N("004370", "2024-01-24", "+", "news", "2023년 신라면 매출 1조2100억(+14%) 사상 최대, 해외 비중 60%",
  "농심은 1월 24일 신라면의 2023년 국내외 매출이 1조2100억원으로 전년보다 14% 늘어 사상 최대를 기록했다고 밝혔어요. 해외 매출 비중이 약 60%에 이르렀고 법인별로 미국 19%, 일본 19%, 호주 26%, 베트남 58% 성장했으며, 미국은 2022년 5월 가동한 제2공장과 코스트코·월마트 판매 확대가 견인했어요. 해외 라면 성장이 수치로 확인된 것이 2018년부터 이어진 장기 상승 국면의 핵심 근거였어요.",
  "https://biz.newdaily.co.kr/site/data/html/2024/01/24/2024012400025.amp.html", "뉴데일리")
