N("298000", "2026-06-15", "-", "cat", "완전자본잠식 거래정지 1년3개월 만에 재개, 첫날 -19%",
  "효성화학은 2024년 재무 기준 완전자본잠식으로 2025년 2월 28일부터 거래가 정지됐다가, 개선기간 1년을 거쳐 2026년 6월 15일 거래를 재개했어요. 기준가는 7만7800원이었지만 1년 넘게 묶였던 기존 주주들의 매물이 쏟아지며 오전 9시44분 19.02% 내린 6만3000원에 거래됐어요. 2022~2025년 4년 연속 영업손실과 자본잠식이 2023년부터 이어진 -85% 하락 국면의 본질이었고, 거래 재개 직후 매도가 그 마지막 구간이었어요.",
  "https://www.mt.co.kr/article/2026061509570957926", "머니투데이")
N("298000", "2026-07-07", "+", "cat", "IBK '2분기 영업익 1000억 이상' 리포트에 상한가 6.7만원",
  "IBK투자증권이 효성화학의 2분기 영업이익이 1000억원을 넘을 것으로 전망하자 7월 7일 주가가 29.84% 올라 상한가 6만7000원을 기록했어요. 1분기 영업이익은 3억원에 그쳤지만 PP 판가 상승, 프로판 원가 래깅 효과, 베트남 공장 안정화가 개선 요인으로 꼽혔고, 자산매각·외부 조달 약 1조6414억원으로 이자비용이 2024년 1776억원에서 약 800억원으로 줄 전망이에요. 실적 턴어라운드 기대가 거래 재개 후 6~7월 반등 국면을 이끌었지만 높은 부채비율은 여전한 위험으로 지적됐어요.",
  "https://www.mt.co.kr/article/2026070709410052379", "머니투데이")
