N("267250", "2025-10-23", "+", "cat", "정기선 회장 승진·조선 계열사 합병에 신고가 18.08만원, 10월 +16%",
  "HD현대는 정기선 수석부회장의 회장 승진으로 약 30년 만에 오너 경영 체제가 복귀하자 6일 연속 올라 장중 52주 신고가 18만800원을 기록했고 10월 상승률은 16.28%였어요. HD현대중공업·HD현대미포 합병(12월 1일)과 HD현대건설기계·인프라코어 합병(2026년 1월 HD건설기계 출범) 등 사업 재편, 미국 MASGA 프로젝트 기대도 겹쳤어요. 그룹 상장사 10곳이 모두 큰 폭으로 올랐어요. 지배구조 정비와 조선 슈퍼사이클이 지주사 HD현대의 장기 상승 국면 후반을 끌어올렸어요.",
  "https://view.asiae.co.kr/article/2025102216284063897", "아시아경제")
N("457190", "2024-02-06", "+", "cat", "이수엑사켐 정밀화학 합병·5대1 액면분할 발표에 +26.54%",
  "이수스페셜티케미컬은 2월 5일 장 마감 후 이수엑사켐 정밀화학 사업부문 합병을 공시했고, 6일 오전 26.54% 오른 24만7500원에 거래되며 1일부터 4거래일 연속 상승했어요. 3월 주총을 거쳐 5대1 액면분할로 발행주식이 559만8773주에서 3020만2985주로 늘어날 예정이었어요. 회사는 판매조직 강화와 생산·유통 일원화로 비용 절감과 매출 증대를 기대한다고 밝혔어요. 합병·액면분할 이벤트가 2023년 10월~2024년 4월 상승 국면의 주요 촉매였어요.",
  "https://core.asiae.co.kr/article/2024020610074442651", "아시아경제")
