# ---- SK이노베이션(096770)
N("096770", "2024-08-05", "-", "cat", "SK E&S 합병 후 주가 10.02만원, 매수청구가 11.19만원 10% 밑돌아",
  "SK이노베이션 주가는 8월 5일 3.93% 내린 10만200원으로, 7월 17일 SK E&S 합병 결의 때 정해진 주식매수청구가 11만1943원보다 약 10.49% 낮았어요. 2분기 실적 부진으로 목표가 하향이 잇따랐고, 매수청구 규모가 8000억원을 넘으면 회사가 합병 조건을 바꾸거나 취소할 수 있어 주주들의 청구 압박이 커졌어요. 이날 코스피도 4.32% 급락했어요. SK온 적자와 그룹 재편에 대한 주주 불신이 2023년 7월~2025년 5월 하락 국면을 길게 끌고 간 배경이었어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/56670", "스마트투데이")
