  "2025년 10월 29일 증권사들이 ESS 사업 성장을 근거로 목표가를 일제히 올리면서 주가가 장중 5.45% 오른 32만9000원을 기록했어요. KB증권은 24만원에서 40만원으로, SK증권은 25만원에서 40만원으로 올렸고, 신한은 2026년 ESS 영업이익을 8199억원(+620%)으로 전망했어요. 전기차 부진을 ESS가 대체한다는 'ESS 회사' 재평가가 이 상승 국면의 핵심 논리였어요.",
