  "2025년 11월 10일부터 사흘간 주가가 63.1% 올라 시가총액이 약 2.1조원으로 회복했어요. 3분기 매출 1437억원(전년비 -32%), 영업손실 343억원으로 실적은 부진했지만, 익산 배터리용 동박 라인을 AI 데이터센터용 회로박으로 전환한다는 계획이 부각됐어요. 전기차 동박 회사에서 AI 소재 회사로의 재평가가 이 상승 국면을 이끈 촉매였어요.",
