N("018470", "2026-04-13", "+", "cat", "미·이란 협상 결렬에 알루미늄주 급등, 조일알미늄 약 16%↑",
  "2026년 4월 11일 파키스탄에서 열린 미·이란 협상이 합의 없이 끝나자 13일 오전 남선알미늄이 23%, 조일알미늄이 약 16%, 삼아알미늄이 약 9% 올랐어요. 중동이 세계 알루미늄의 약 9%를 생산해 공급 불안 우려가 커졌다는 해석이었어요. 호르무즈 해협 긴장에 따른 알루미늄 테마가 이 단기 상승 국면의 동력이었어요.",
  "https://view.asiae.co.kr/en/article/2026041310112290118", "아시아경제")
# ---- POSCO홀딩스(005490)
N("005490", "2026-05-04", "+", "earn", "1분기 영업이익 7070억원, 기대치 약 20% 상회에 9% 상승",
  "2026년 5월 4일 1분기 매출 약 17조8760억원, 영업이익 약 7070억원으로 시장 기대치를 약 20% 웃도는 실적이 확인되며 주가가 장중 9.09% 오른 50만5000원을 기록했어요. 리튬 사업 회복 기대가 함께 부각됐어요. 4월 고점 이후 하락 국면 초입에 나온 실적 서프라이즈였지만, 추세를 되돌리지는 못한 반등이었어요.",
  "https://www.mt.co.kr/article/2026050413592119461", "머니투데이")
# ---- 금양(001570)
N("001570", "2026-03-30", "-", "cat", "2년 연속 감사의견 거절, 상장폐지 수순(고점 19.4만원→9900원)",
  "2026년 3월 30일 외부감사인 신한회계법인이 2025년 재무제표에 2년 연속 의견거절을 냈다고 공시했어요. 2025년 영업손실 418억원, 순손실 536억원에 유동부채가 유동자산을 6112억원 초과해 계속기업 존속에 중대한 의문이 제기됐고, 사우디 투자자 대상 4050억원 유상증자는 일곱 차례 연기됐어요. 2023년 7월 26일 장중 19만4000원(시총 약 9조원) 고점에서 9900원까지 떨어진 이 하락 국면의 결정타였어요.",
  "https://news.tf.co.kr/read/economy/2307567.htm", "더팩트")
N("006400", "2026-04-21", "+", "cat", "벤츠 차세대 전기차 배터리 수주에 10% 급등, 59.6만원 신고가",
  "2026년 4월 21일 메르세데스-벤츠 차세대 전기차용 하이니켈(니켈 80% 이상) NCM 각형 배터리를 2028년부터 다년간 공급하는 계약 소식에 주가가 장중 10.22% 오른 59만2500원을 기록했고, 장중 59만6000원으로 신고가를 썼어요. 이로써 독일 3사(벤츠·BMW·아우디)에 모두 공급하는 유일한 국내 배터리사가 됐어요. 2025년 5월 저점 이후 +311% 상승 국면의 정점 부근에서 나온 대형 수주였어요.",
  "https://v.daum.net/v/20260421103616533?sicode=01", "다음(뉴스)")
N("006400", "2026-07-09", "-", "cat", "다올, 목표가 90만원→77만원 하향…2분기 영업손실 490억원 전망",
  "2026년 7월 9일 다올투자증권이 실적 회복에 근거가 더 필요하다며 목표가를 90만원에서 77만원으로 낮췄어요. 2분기 매출 약 3.7조원, 영업손실 약 490억원(AMPC 제외 시 약 -1360억원)으로 여전히 적자가 이어질 것으로 봤어요. 4월 신고가 이후 -43% 조정 국면에서 기대가 실적을 앞서갔다는 점이 확인된 셈이었어요.",
  "https://biz.sbs.co.kr/amp/article/20000321491", "SBS Biz")
# ---- TCC스틸(002710)
N("002710", "2024-03-12", "-", "earn", "2023년 영업이익 113억원(-74.4%), 순손실 전환",
  "2024년 3월 공시된 2023년 실적은 매출 6244억원(-8.8%), 영업이익 113억원(-74.4%), 순손실 76억원으로 적자 전환이었어요. 중국산 수입 증가와 고금리 속 식음료 고객사 구매 축소로 주석도금강판 판매가 줄었고, 차입금은 2729억원(2023년 3분기)으로 늘었어요. 2024년 2월 고점 이후 -88% 하락 국면 초입에 이차전지 기대와 동떨어진 본업 부진이 드러난 사건이었어요.",
  "https://newstomato.com/ReadNews.aspx?no=1222572", "IB토마토")
# ---- 포스코퓨처엠(003670)
N("003670", "2026-01-26", "+", "news", "리튬 2년 만의 최고·로봇 배터리 기대에 4.67% 상승",
  "2026년 1월 26일 주가가 장중 4.67% 오른 22만4000원을 기록했어요. 1월 23일 리튬 가격이 전월 평균 대비 47.24% 오른 kg당 17.58달러로 약 2년 만의 최고치를 찍었고, 휴머노이드 로봇용 배터리 수요 기대와 테슬라의 중국산 부품 배제 보도가 양극재주 매수를 불렀어요. 2025년 5월 저점 이후 +54% 상승 국면에서 리튬 반등이 핵심 동력이었음을 보여줘요.",
  "https://www.mt.co.kr/article/2026012611325260591", "머니투데이")
# ---- SKC(011790)
N("011790", "2026-05-29", "-", "cat", "유리기판 양산 3년 지연, 1.17조원 유상증자 중 5896억원 앱솔릭스 투입",
  "2026년 5월 29일 보도에 따르면 미국 자회사 앱솔릭스의 AI 반도체용 유리기판 상용화가 당초 2024년 6월 목표에서 약 3년 밀렸고, 최근 공시에서 구체적 양산 일정을 예측하기 어렵다고 밝혔어요. 누적 투자 4174억원에 1조1671억원 유상증자의 절반인 5896억원을 추가 투입할 계획이고, 미국 칩스법 보조금 잔여 3500만달러는 못 받을 수도 있어요. 유리기판 기대로 오른 주가가 5월 고점 이후 -47% 하락 국면으로 꺾인 배경이에요.",
  "https://biz.sbs.co.kr/amp/article/20000313349", "SBS Biz")
N("011790", "2026-04-07", "-", "cat", "약 1조원 유상증자 발표 후 주가 17% 하락, 발행가 8.53만→7.06만원",
  "SKC는 2026년 2월 말 약 1조569억원(예정 발행가 8만5300원, 할인율 20%) 규모 유상증자를 결의했어요. 결의 직전 11만3000원대였던 주가는 4월 2일 9만3600원으로 17% 넘게 떨어졌고, 1차 발행가가 7만600원으로 낮아져 조달액이 약 8280억원으로 줄었어요. 유리기판 기대로 오르던 상승 국면 중간에 대규모 지분 희석이 주가를 끌어내린 사건이었어요.",
  "https://biz.sbs.co.kr/amp/article/20000302562", "SBS Biz")
# ---- 율촌화학(008730)
N("008730", "2024-07-31", "-", "cat", "1.49조원 배터리 파우치 공급계약 해지에 24% 급락, 52주 신저가",
  "2024년 7월 31일 지난해 매출의 358%에 해당하는 1조4872억원 규모 리튬이온 배터리용 알루미늄 파우치 공급계약(2023~2028년) 해지 소식에 주가가 장중 24.42% 내린 2만2750원을 기록했어요. 장중 저가는 2만1100원으로 1월의 52주 신저가 2만4950원을 갈아치웠어요. 2024년 2월 이후 -50% 하락 국면을 결정지은 회사 고유 악재였어요.",
  "https://view.asiae.co.kr/article/2024073109484928122", "아시아경제")
# ---- 세방전지(004490)
N("004490", "2024-05-09", "+", "news", "하이브리드차 AGM 배터리 수요에 3일 연속 52주 신고가, 11.44만원",
  "2024년 5월 9일 주가가 장중 2.60% 오른 11만4400원으로 사흘 연속 52주 신고가를 쓰며 2021년 6월 이후 최고 수준에 올랐어요. 1분기 국내 하이브리드차 판매가 11만1766대로 39.6% 늘었고, DS투자증권은 1분기 영업이익을 약 460억원(전년비 약 +209%)으로 추정했어요. 내연기관 납축전지에서 AGM 배터리로 체질이 바뀐다는 기대가 2022년 10월 이후 +167% 상승 국면의 핵심이었어요.",
  "https://view.asiae.co.kr/article/2024050909375855367", "아시아경제")
N("004490", "2024-08-19", "+", "earn", "2분기 영업이익 590억원(+87%) 기대 상회에 4.81% 반등",
  "2024년 8월 19일 2분기 매출 5196억원(+31%), 영업이익 590억원(+87%), 영업이익률 11.4%로 시장 기대를 웃돈 실적이 부각되며 주가가 4.81% 오른 10만4600원을 기록했어요. 다만 6월 고점(11만원대)을 넘지 못했고, 이후 -50% 하락 국면이 이어져 호실적이 주가 추세를 바꾸지는 못했어요.",
  "https://core.asiae.co.kr/article/2024081911543962287", "아시아경제")
# ---- 동원시스템즈(014820)
N("014820", "2025-12-24", "-", "earn", "3분기 영업이익 202억원(-28%), 고점 4.245만원 대비 36% 하락·PBR 1배 하회",
  "2025년 12월 보도에 따르면 3분기 매출은 3564억원으로 소폭 늘었지만 영업이익은 원가 상승으로 202억원(-28%)에 그쳤고, PBR은 0.93배로 올해 처음 1배 아래로 내려갔어요. 주가는 2024년 12월 24일 52주 최고 4만2450원에서 2만6100원까지 떨어졌어요. 원통형 배터리 캔 등 이차전지 신사업 성과 지연으로 성장 프리미엄이 빠진 것이 2024년 10월 이후 하락 국면의 배경이에요.",
  "https://news.tf.co.kr/read/economy/2270282.htm", "더팩트")
# ---- 코스모신소재(005070)
N("005070", "2023-08-18", "-", "cat", "약 2284억원 유상증자 발표, 발행가 12.28만→11.04만원으로 하향",
  "코스모신소재는 2023년 8월 18일 유상증자를 발표했고(당일 종가 15만3000원), 주가 하락으로 주당 발행가가 12만2800원에서 11만400원으로 낮아지며 최종 조달액이 약 2284억원에서 2053억원으로 줄었어요. 11월 2일 종가는 14만8500원이었어요. 2023년 6월 고점 이후 -82% 하락 국면 초입에서 양극재 설비 투자를 위한 대규모 지분 희석이 수급 부담으로 작용했어요.",
  "https://newstomato.com/ReadNews.aspx?no=1207006", "IB토마토")
# ---- 코스모화학(005420)
N("005420", "2023-08-18", "-", "cat", "자회사와 동시 유상증자, 발행가 3.455만→3.27만원·조달액 1112억원",
  "모회사 코스모화학도 2023년 8월 18일 자회사 코스모신소재와 함께 유상증자를 발표했고, 주가 하락으로 최종 발행가가 3만4550원에서 3만2700원(약 -5.35%)으로 낮아져 조달 예정액이 약 1175억원에서 1112억원으로 줄었어요. 2023년 4월 고점 이후 -84% 하락 국면에서 첫 대형 희석 이벤트였어요.",
  "https://newstomato.com/ReadNews.aspx?no=1207006", "IB토마토")
N("005420", "2025-10-13", "-", "news", "연속 적자·잉여현금흐름 -2274억원, 단기차입 3656억원 vs 현금 154억원",
  "2025년 10월 보도에 따르면 코스모화학은 지난해 연간 적자에 이어 올해 상반기에도 38억원 손실을 냈고, 잉여현금흐름은 2023년 약 -2290억원, 2024년 약 -2274억원이었어요. 상반기 말 사채 포함 단기차입금이 3656억원인데 현금성 자산은 154억원에 그쳤어요. 이차전지 소재 투자 회수에 대한 의구심이 장기 하락 국면을 이어가게 한 재무 부담이었어요.",
  "https://www.ibtomato.com/View.aspx?no=16228&type=2", "IB토마토")
# ---- LG화학(051910)
N("051910", "2025-10-22", "+", "cat", "행동주의 펀드 팰리서 '74% 디스카운트' 지적에 7.66% 급등",
  "2025년 10월 22일 지분 1% 이상을 보유한 영국계 행동주의 펀드 팰리서캐피탈이 LG화학이 대기업 중 가장 낮은 74% 디스카운트로 거래된다며 LG에너지솔루션 지분을 활용한 자사주 매입 등 4가지 제안을 내놓자 주가가 장중 7.66% 오른 37만2500원을 기록했어요. 자회사 지분가치가 주가에 반영되지 않았다는 주장이 부각됐어요. 2025년 5월 저점 이후 +112% 상승 국면에서 지배구조·주주환원 재평가가 핵심 촉매였어요.",
  "https://view.asiae.co.kr/article/2025102209410630067", "아시아경제")
N("051910", "2026-03-09", "-", "macro", "미·이스라엘의 이란 공습에 석유화학 불가항력 우려, 일주일 새 28% 급락",
  "2026년 3월 9일 LG화학은 8.12% 내린 30만원에 마감해 3~9일 일주일 동안 28.14% 떨어졌어요. 미국·이스라엘의 이란 공습으로 중동산 나프타 수급 차질과 석유화학사들의 불가항력 선언(여수NCC 3월 4일) 우려가 커졌기 때문이에요. 2월 고점 이후 -45% 하락 국면을 연 것은 회사 고유 악재보다 본업 석유화학을 덮친 중동발 충격이었어요.",
  "https://mobile.newsis.com/view/NISX20260309_0003540796", "뉴시스")
N("001570", "2025-03-28", "-", "cat", "4.5조 유증 철회·불성실공시·감사의견 거절로 거래정지, 시총 9조→6333억원",
  "금양은 2024년 9월 4조5000억원 유상증자를 결의했다가 2025년 1월 주주 반발로 철회해 불성실공시법인·관리종목으로 지정되고 코스피200에서 빠졌어요. 연결 영업손실은 2023년 146억원, 2024년 560억원으로 커졌고, 2025년 3월 21일 한울회계법인의 감사의견 거절로 거래가 정지됐어요(종가 9900원, 3월 28일 시총 6333억원). '밧데리 아저씨' 테마로 시총 9조원을 넘던 주가가 -94% 하락 국면으로 무너진 핵심 공시 사건들이에요.",
  "https://www.newsis.com/view/NISX20250328_0003118230", "뉴시스")
N("005490", "2026-01-28", "+", "news", "리튬 가격 연초 대비 24.5% 반등에 5.15% 상승, 1월 누적 +23.9%",
  "2026년 1월 28일 POSCO홀딩스는 5.15% 오른 37만8000원에 마감해 1월 상승률이 23.93%에 달했어요. 리튬 가격이 1월 27일 kg당 17.52달러로 2025년 말보다 24.52% 올라 리튬 사업 적자 축소 기대가 커졌고, 외국인과 기관이 각각 1573억원, 1554억원을 순매수했어요. 광양 2공장·아르헨티나 염호 가동이 맞물린 리튬 회복 기대가 2025년 5월 이후 +85% 상승 국면의 동력이었어요.",
  "https://www.hankyung.com/article/2026012995946", "한국경제")
