N("025900", "2023-10-12", "+", "news", "이차전지 순환매에 전해액 자회사 부각, 13.05% 급등",
  "2023년 10월 12일 이차전지주 매수세 속에 SK온에 전해액을 공급하는 자회사 동화일렉트로라이트가 부각되며 주가가 13.05% 오른 7만7100원(시총 약 1조5586억원)에 마감했어요. 3분기 전해액 매출은 357억원, 영업이익 54억원이었지만, NH는 400억원 유상증자에 따른 자회사 지분 희석을 이유로 목표가를 5만5000원에서 5만원으로, 하나는 13만600원에서 11만5000원으로 낮췄어요. 2023년 8~11월 +92% 반등 국면이 실적보다 테마 수급에 기댄 것이었음을 보여줘요.",
  "https://thecommoditiesnews.com/news/articleView.html?idxno=6597", "CNews")
