# ---- 비츠로셀(082920)
N("082920", "2026-08-28", "-", "earn", "2분기 영업익 188~196억, 예상 226억 하회·5월 고점 대비 반토막",
  "비츠로셀은 5월 6만원대 중반 고점에서 3개월 만에 3만원대로 떨어져 주가가 반토막 났어요. 상반기 리튬 1차전지 수요 기대를 자극한 중동 정세 불안이 완화되며 테마성 매수세가 빠졌고, 2분기 영업이익도 약 188억~196억원으로 시장 예상치 226억원을 밑돌았어요. 2차전지 피어 평균 PER이 52.6배에서 40.3배로 낮아진 것도 부담이었어요. 지정학 테마 소멸과 실적 미달이 겹친 것이 이번 하락 국면의 핵심이에요.",
  "https://www.hankyung.com/article/202608288415i", "한국경제")
# ---- 후성(093370)
N("093370", "2026-06-16", "+", "cat", "6월에만 +67%·투자경고 지정, 특수가스·불산·LiPF6 가격 급등",
  "후성 주가는 6월 들어 67% 급등해 투자경고 종목으로 지정됐고, 6월 16일 종가 1만9,200원 기준 연초 대비 158% 올라 2022년 이후 최고가 수준이었어요. 중국 텅스텐 수출 통제와 일본 업체 감산으로 WF6 판가 인상 기대가 커졌고, 중동 전쟁에 따른 불산 원료 가격 상승, LiPF6 풀가동 추정이 겹쳤어요. 팔로워 84만명의 X 계정 '세레니티'가 언급하며 개인 매수도 몰렸어요. 다만 6월 16일 하루 14.29% 급락했고 2026년 예상 PER이 약 93배여서 급등 국면의 정점 신호이기도 했어요.",
  "https://view.asiae.co.kr/article/2026061717475099542", "아시아경제")
# ---- 엘앤에프(066970)
N("066970", "2025-12-30", "-", "cat", "테슬라 3.8조 양극재 계약 973만원으로 축소 공시, -11.7%",
  "2023년 테슬라와 맺은 3조8,347억원 규모 하이니켈 양극재 공급 계약이 물량 변경으로 973만316원으로 줄었다는 공시가 나오자 주가가 장 초반 11.74% 떨어진 9만3,200원에 거래됐어요. 테슬라의 4680 배터리 양산 계획 재검토와 북미 전기차 수요 둔화가 배경으로 풀이됐어요. 다만 유안타증권은 해당 계약 매출이 거의 없어 실적 영향은 제한적이라고 봤고, 상승 국면 중 일시적 충격에 그쳤어요.",
  "https://view.asiae.co.kr/article/2025123009293731468", "아시아경제")
N("066970", "2026-04-07", "+", "cat", "삼성SDI 1.6조 LFP 계약·1분기 흑자 기대에 18만원 돌파(+9%)",
  "엘앤에프 주가가 장중 9.20% 오른 18만6,300원을 기록하며 18만원선을 넘었어요. 전달 삼성SDI와 1조6,000억원 규모 LFP 양극재 공급 계약을 맺었고, 탄산리튬 가격이 2025년 4분기보다 약 20% 오르며 1분기 흑자 기대가 커졌어요. 교보증권은 국내 경쟁사보다 LFP에 일찍 진입해 고객 확대 여지가 크다고 평가했어요. 2025년 6월부터 이어진 +296% 상승 국면의 정점 부근 사건이에요.",
  "https://news.mtn.co.kr/news-detail/2026040711515649546", "머니투데이방송")
