N("084850", "2026-04-13", "-", "cat", "주요 고객 애플과 스마트폰 보호회로 거래 중단 공시",
  "아이티엠반도체가 4월 13일 공시로 주요 고객사 애플과의 스마트폰 보호회로 사업 거래를 중단한다고 밝혔어요. 회사는 저수익 구조를 벗어나기 위한 결정이라며 삼성전자 플래그십 진입으로 보호회로 매출을 2배 이상 늘리고 하반기 턴어라운드를 노린다고 했어요. 2025년 말부터 이어진 +74% 반등이 끝나고 -71% 하락 국면이 시작된 시점의 핵심 공시예요.",
  "https://www.hankyung.com/article/202604148886i", "한국경제")
N("084850", "2026-08-10", "-", "news", "베트남 법인 928만달러 횡령·영구 EB 금리 7% 스텝업",
  "베트남 법인 현지 직원의 자금 유용으로 928만달러 횡령이 발생해 회수가 어려운 약 681만달러를 손실 처리했고, 지난해 순손실은 잠정치보다 171억원 늘어난 936억원으로 확정됐어요. 2023년 발행한 영구 EB의 금리가 연 2.5%에서 7%로 올라 200억원을 단기 차입해 상환하고 200억원 CB를 새로 발행하기로 했어요. 1분기에도 매출 1,322억원에 영업손실 49억원이었고 여신한도 미사용분은 2.5%뿐이어서, 하락 국면에서 유동성 우려를 키운 요인이에요.",
  "https://newstomato.com/ReadNews.aspx?no=1309819", "뉴스토마토")
