  "SK이노베이션이 5월 16일 장중 8만7,200원으로 52주 신저가를 기록했어요. 미국 하원 공화당 IRA 수정안의 전기차 보조금 조기 종료와 AMPC 축소 우려에 배터리 업종 전반이 약세였어요. 회사 고유 사건이라기보다 업종 악재가 겹친 것으로, 2023년 7월부터 이어진 -58% 하락 국면의 저점 부근이에요.",
