  "피엔티의 2026년 상반기 연결 매출은 2,190억원으로 17.4% 줄었고 영업이익은 125억원으로 66.2% 감소했어요. 수주잔고도 2023년 말 1조9,256억원에서 상반기 말 1조5,510억원으로 줄었는데, ESS 수요 증가에도 고객사들이 신규 라인 대신 유휴 설비 전환으로 대응해 장비 수주로 이어지지 않았어요. 2024년 정점(매출 1조350억원, 영업이익 1,640억원) 이후 실적 하락이 이어진 것이 2026년 4월 이후 하락 국면의 배경이에요.",
