# ---- 에코프로비엠(247540)
N("247540", "2026-02-07", "-", "earn", "2025년 영업이익 1,428억 흑자전환에도 '이익의 질' 의문",
  "에코프로비엠은 2025년 매출 2.5조원, 영업이익 1,428억원으로 흑자 전환했지만, 4분기 재고평가손 환입과 유형자산 내용연수 조정(감가상각비 약 400억원 감소)이 이익을 끌어올린 것이라는 평가가 나왔어요. 2월 초 주가 급등은 코스닥 부양책과 ETF 자금 유입 덕분이라는 분석이었고, iM증권·신영증권은 중립 의견을 냈어요. 포드-SK온 미국 합작 청산으로 SK온향 양극재 판매가 23% 줄 것이란 전망까지 겹쳐, 1월 고점 이후 하락 국면의 펀더멘털 근거가 됐어요.",
  "https://www.koreatimes.co.kr/amp/business/companies/20260207/skepticism-persists-over-ecopro-bm-despite-2025-profit-rebound", "코리아타임스")
