  "나인테크 주가가 2025년 2월 11일 장중 18.75% 오른 2,755원을 기록했어요. 회사가 팬아웃 패널레벨패키징(FO-PLP)과 유리기판용 장비 개발·테스트를 마쳤고, TGV 습식 식각 파일럿 장비를 확보했다는 소식에 삼성전자·TSMC의 차세대 AI칩 로드맵 수혜 기대가 붙었어요. 2025년 1월 저점 이후 +151% 상승 국면을 연 유리기판 테마 편입 계기예요.",
