N("259630", "2026-04-21", "+", "cat", "삼성SDI-벤츠 협력·전고체 파일럿 장비 수주로 장중 +10.6%",
  "엠플러스 주가가 2026년 4월 21일 장중 10.64% 오른 17,680원을 기록했어요. 전날 삼성SDI가 메르세데스-벤츠와 배터리 공급망 협력을 발표하고 벤츠 CTO가 전고체 배터리 협의를 언급하자, 4월 9일 전고체 양산 난제 해결 장비 개발과 파일럿 장비 수주를 밝힌 엠플러스가 주목받았어요. 2026년 4월 고점 직전 전고체 테마가 상승 국면의 마지막 동력이 된 장면이에요.",
  "https://etoday.co.kr/news/view/2577590", "이투데이")
