  "NH투자증권은 2026년 1월 23일 솔브레인 목표가를 38만5000원으로 올리고 적용 PER을 20.4배로 높였어요. 2025년 4분기 매출은 2436억원(+12.5%), 영업이익 395억원(+8.6%)으로 실적 추정치는 바꾸지 않았어요. 실적보다 반도체 소재 밸류에이션 재평가가 이 상승 국면의 막바지를 이끌었다는 뜻이에요.",
