  "성일하이텍 주가는 2026년 1월 29일 7만1800원으로 2025년 4월 9일 저점 3만100원 대비 138.5% 올랐어요. 1월 기준 리튬 가격은 kg당 10.09달러에서 17.87달러(+77.1%), 코발트는 21.91달러에서 54.80달러(+150.1%)로 뛰었고 폐배터리 발생량 증가와 EU 재활용 원료 의무화도 부각됐어요. 메탈 가격 반등이 재활용 업체 실적 기대를 되살린 것이 이 상승 국면의 동력이었어요.",
