  "성우는 수요예측 경쟁률 516대 1로 공모가를 희망밴드(2만5000~2만9000원) 상단을 넘는 3만2000원에 확정했고, 공모 규모 약 960억원으로 그해 코스닥 최대였어요. 하지만 2024년 10월 31일 상장 첫날 오전 주가는 공모가보다 8.28% 낮은 2만9350원에 거래됐어요. 밴드 상단을 넘긴 고평가 공모가에서 출발한 것이 이후 장기 하락 국면의 시작점이었어요.",
