  "엔시스의 2025년 상반기 매출은 280억9300만원으로 전년 동기보다 10.5% 줄었고, 영업손실 34억2300만원, 순손실 38억3400만원을 냈어요. 회사는 주요 거래처 갑진이 법정관리에 들어가면서 관련 매출채권·재고 약 56억원에 대손충당금을 반영했다고 설명했어요. 고객사 부실이 실적 적자로 이어진 것이 이 장기 하락 국면의 회사 고유 악재였어요.",
