N("033160", "2026-04-10", "+", "news", "소캠(SOCAMM) 수요 기대에 11.5% 급등, 52주 신고가",
  "4월 10일 주가가 전날보다 11.54% 오른 2만1650원에 거래됐고 장중 2만2500원까지 올라 52주 신고가를 새로 썼어요. 현대차증권은 국내 법인의 금 와이어 본딩 수요가 월평균 7만km 안팎으로 전년(5~6만km)보다 강하고, 소캠2 양산 본격화로 2분기에도 수요가 강할 것으로 봤어요. 상승 국면의 고점 부근에서 실적 개선 기대가 정점에 달한 장면이에요.",
  "https://view.asiae.co.kr/article/2026041010432699906", "아시아경제")
# ---- SFA반도체(036540)
N("036540", "2024-01-24", "+", "cat", "두산 인수설에 장중 8150원, 10% 급등(회사는 부인)",
  "1월 23일 두산그룹이 SFA반도체 인수를 검토한다는 보도가 나오자, 24일 반도체주 약세 속에서도 주가가 10.14% 오른 7600원(장중 8150원)에 거래됐어요. 거래대금은 삼성전자 다음으로 많은 4000억원을 넘었어요. 다만 회사는 매각을 추진하지 않는다고 부인했어요. 2024년 1월 고점을 만든 인수설 테마로, 이후 기대가 꺼지며 하락 국면이 시작됐어요.",
  "https://www.fnnews.com/news/202401241037213652", "파이낸셜뉴스")
N("036540", "2026-09-22", "+", "news", "일주일새 49.9% 급등, 외국인 529억 순매수",
  "9월 21일까지 일주일간 주가가 49.86% 올라 같은 기간 삼성전자(5.59%), SK하이닉스(3.09%)를 크게 웃돌았어요. 외국인이 529억원을 순매수했고, 메모리 업체들이 범용 메모리 후공정 외주 비중을 늘린다는 점이 부각됐어요. 하나증권은 증설 일정상 2028년까지 외형 성장 가시성이 매우 높다고 봤어요. 2025년 4월 이후 상승 국면을 가속한 사건이에요.",
  "https://www.mt.co.kr/article/2026092215234069115", "머니투데이")
N("031330", "2026-08-06", "-", "news", "1분기 영업익 3273억 사상 최대에도 영업현금흐름 -3814억, 차입 급증",
  "2026년 1분기 연결 매출 1조7954억원(+135%), 영업이익 3273억원(+1578%)으로 사상 최대였지만 영업활동현금흐름은 -3814억원이었어요. 재고자산이 6857억원에서 1조3650억원으로 거의 두 배가 됐고 단기차입금은 4618억원에서 8729억원으로, 부채비율은 183%에서 213%로 올랐어요. 원화 10% 약세 시 세전손익 영향도 -415억원으로 바뀌었어요. 하락 국면에서 실적보다 재고·달러빚 부담이 부각된 장면이에요.",
  "https://www.newstomato.com/ReadNews.aspx?no=1309231", "IB토마토")
N("033160", "2026-05-15", "+", "earn", "1분기 연결 매출 4501억·영업익 151억, 별도 영업익 +132%",
  "5월 15일 공시한 1분기 별도 매출은 2887억원(+86%), 영업이익은 86억원(+132%)이었고 중국법인 영업이익은 204% 늘었어요. 연결 기준 매출 4501억원, 영업이익 151억원, 순이익 115억원이에요. 기사에 컨센서스 비교는 없어요. 고점 직후 실적은 좋았지만 주가 하락을 막지 못했어요.",
  "https://view.asiae.co.kr/article/2026051516045093260", "아시아경제")
N("033160", "2026-08-28", "-", "cat", "본딩와이어·솔더볼 담합 기소, 고점 대비 -62%",
  "서울중앙지검이 8월 13일 법인과 전·현직 대표 등 5명을 공정거래법 위반으로 불구속기소했어요. 관련 매출은 본딩와이어 3069억원, 솔더볼 407억원 등 3476억원이에요. 8월 28일 주가는 4.53% 내린 1만3920원으로 52주 최고가 3만7000원 대비 62.4% 빠졌고, 대주주 지분 75.76%가 담보로 잡혀 있고 EB 오버행 우려도 지적됐어요. 하락 국면을 깊게 만든 회사 고유 악재예요.",
  "https://www.sidae.com/article/2026082816120265555", "시대")
# ---- 피에스케이홀딩스(031980)
N("031980", "2024-05-20", "+", "earn", "1분기 영업익 154억(+10% QoQ), 목표가 5.8만→7.1만원",
  "신한투자증권은 1분기 매출 381억원(-4% QoQ), 영업이익 154억원(+10% QoQ)으로 HBM 공정 장비 판매 단가가 일반 D램용의 3~5배 수준이라 수익성이 좋아졌다고 분석했어요. 1분기 국내 매출 310억원은 지난해 연간의 3분의 1에 달했고, 2024년 매출 1678억원(+77%)·영업이익 614억원(+127%)을 전망하며 목표가를 5만8000원에서 7만1000원으로 올렸어요. 국내 HBM 밸류체인 중 HBM 매출 비중이 가장 높다는 점이 2024년 6월 고점까지의 상승을 이끈 핵심 논리였어요.",
  "https://view.asiae.co.kr/en/article/2024052007503904551", "아시아경제")
# ---- 네패스(033640)
N("033640", "2025-12-26", "+", "news", "창업주 지분 증여로 이창우 대표 최대주주(23.53%), 주가 53.5% 상승",
  "6월 16일 이병구 창업주 부부의 지분 전량을 증여받아 이창우 대표의 지분이 1.09%에서 23.53%로 늘며 최대주주가 됐어요. 증여세는 약 240억원으로 추산되고, 130만 주를 연부연납 담보로 공탁하고 38만여 주로 23억원 주식담보대출을 받았어요. 후공정 수주 회복과 가동률 정상화로 실적이 개선됐고 기사는 주가가 9380원에서 1만4400원으로 약 53.5% 올랐다고 전했어요. 상승 국면에서 승계 마무리와 실적 회복이 겹친 배경이에요.",
  "https://dealsite.co.kr/articles/153963", "딜사이트")
# ---- 유니셈(036200)
N("036200", "2024-06-24", "+", "news", "HBM·TSV 공정 스크러버 공급, 극저온 칠러 단가 4배 기대",
  "유니셈은 지난해 말부터 주요 고객사 HBM 제조 공정과 TSV 공정에 플라즈마 스크러버를 공급했고, 삼성전자·SK하이닉스의 HBM 증설에 따른 추가 수주가 기대됐어요. 차세대 낸드용 극저온 식각에는 고성능 칠러가 필요해 신규 칠러 가격이 기존의 약 4배가 될 것으로 업계는 봤어요. 지난해 실적은 매출 2321억원, 영업이익 174억원이에요. 2024년 6월 고점 부근에서 HBM 수혜 기대가 정점에 달했던 장면이에요.",
  "https://zdnet.co.kr/view/?no=20240618075955", "지디넷코리아")
N("036200", "2025-08-18", "+", "news", "6월 말 대비 37.4% 상승, 2025년 영업익 +144% 전망",
  "주가가 6월 말 대비 37.4% 올라 코스닥 대비 33.4%포인트 초과 수익을 냈고 기관이 94억원을 순매수했어요. 한국IR협의회는 2025년 매출 2650억원(+21.5%), 영업이익 243억원(+144.0%)을 예상하며 2021년 이후 역성장에서 벗어나는 회복 초입이라고 평가했어요. SK증권은 D램 신규 투자 장비 반입이 2분기부터 시작됐다고 봤어요. 2025년 5월 저점 이후 반등 국면의 근거가 된 실적 회복 기대예요.",
  "https://core.asiae.co.kr/article/2025081416022943025", "아시아경제")
N("033160", "2025-03-30", "+", "earn", "2024년 영업익 657억(+41.4%), 금값 연동으로 매출 1.17조",
  "2024년 연결 매출은 1조1690억원(+4.7%), 영업이익은 657억원(+41.4%)이었어요. 원재료 매입의 98.95%가 금이라 금값 상승분을 가격 연동으로 전가했고, 국내 본딩와이어 매출(1958억원)과 수출(5102억원)이 모두 늘었어요. 3월 28일 주가는 7230원으로 2024년 말(6580원)보다 약 9% 높았지만 기사는 실적 개선이 아직 주가에 덜 반영됐다고 봤어요. 2024년 12월 저점 이후 상승 국면 초입의 실적 근거예요.",
  "https://thecommoditiesnews.com/news/articleView.html?idxno=8993", "더코모디티뉴스")
N("031330", "2025-12-09", "+", "news", "D램 가격 상승 수혜, 2025년 매출 3.95조·영업익 980억 전망",
  "리서치알음은 D램 가격 상승 수혜를 근거로 에스에이엠티의 올해 매출을 3조9500억원(+36.9%), 영업이익을 980억원(+45.4%)으로 전망하고 적정주가 2만1000원을 제시했어요. 메모리 유통 업체로서 가격 상승이 곧 실적 개선으로 이어진다는 논리예요. 2023년 10월 이후 상승 국면 후반부를 받친 실적 기대예요.",
  "https://www.asiae.co.kr/en/article/2025120907330462608", "아시아경제")
N("031330", "2026-06-04", "+", "cat", "투자경고 지정해제 후 15.9% 급등, 시총 1.8조 돌파",
  "6월 4일 종가가 전일 대비 15.92% 오른 1만8860원으로 거래량 370만 주, 시가총액 1조8000억원을 넘었어요. 6월 2일 투자경고종목 지정해제(재지정 예고 포함) 공시가 수급에 영향을 줬고, HBM 테마가 6.35% 오르는 등 AI 반도체 유통 기대가 겹쳤어요. 재지정 예고로 추가 급등 시 규제 우려도 남았어요. 5월 고점 이후 하락 국면 중 나온 일시적 반등이에요.",
  "https://news.jkn.co.kr/post/925555", "재경일보")
