# ---- 이오테크닉스(039030)
N("039030", "2025-08-19", "+", "earn", "2분기 영업이익 258억, 추정치 73% 상회",
  "이오테크닉스가 2025년 2분기 매출 943억원, 영업이익 258억원을 냈는데 흥국증권 추정치보다 매출은 약 1%, 영업이익은 약 73% 높았어요. 마커·어닐링·커팅·디본더 같은 고수익 반도체 장비 수요가 이익률을 끌어올렸다는 분석이에요. 흥국증권은 목표가를 21만원에서 27만원으로 올렸고, 2025년 4월 저점 이후 반등이 실적으로 증명되는 구간에 들어섰다는 의미였어요.",
  "https://www.hankyung.com/article/2025081973826", "한국경제")
# ---- 솔브레인홀딩스(036830)
N("036830", "2024-02-20", "+", "cat", "IRA 해외우려기업 지침 수혜 기대에 상한가(+29.98%)",
  "솔브레인홀딩스가 2024년 2월 20일 상한가(29.98%)로 8만5400원에 마감했어요. 미국 IRA 해외우려기업(FEOC) 세부지침으로 중국 업체의 소재 공급이 막히면서 국내 이차전지 소재사 반사이익 기대가 커졌고, 2023년 영업이익 1248억원(전년 대비 +69.81%)도 힘을 보탰어요. 이달 초 4만원 선에서 15거래일 중 11거래일 올라 2배 넘게 뛰었는데, 2024년 5월 고점까지 이어진 상승 국면의 막바지 급등을 이끈 이차전지 테마였어요.",
  "https://v.daum.net/v/20240220161926295", "다음(조선비즈 등)")
N("036830", "2025-09-10", "+", "news", "아크 지분 60% 5219억원 매각, 투자 성과 부각",
  "솔브레인홀딩스는 2018년 507억원에 인수한 아크 다이아그노스틱스 지분 60%를 2025년 5219억원에 넘겨 약 4756억원의 현금을 확보하게 됐어요. 기사는 아크 몸값이 7년 만에 약 17배가 됐다고 추정했어요. 다만 지주사 할인, 이차전지·디스플레이 부진, 승계 불확실성 탓에 주가가 투자 성과를 충분히 반영하지 못하고 있다는 평가였어요.",
  "https://v.daum.net/v/20250910060154438", "조선비즈(다음)")
# ---- 주성엔지니어링(036930)
N("036930", "2026-11-04", "+", "earn", "3분기 영업이익 177억, 전년 대비 5배",
  "주성엔지니어링이 2026년 3분기 매출 781억원(전년 대비 +32.8%), 영업이익 177억원(+426.4%)을 냈고 영업이익률이 2.4%에서 22.6%로 뛰었어요. 직전 분기 영업이익 14억원에서 크게 개선된 것으로, SK하이닉스 M15X D램 투자와 CXMT 증설로 High-k ALD 장비 수요가 늘어난 덕분이라는 분석이에요. 5월 글로벌 반도체 기업에 통합 ALG 장비를 처음 출하한 점도 차세대 성장 기대를 받쳤어요.",
  "https://inews24.com/view/2022644", "아이뉴스24")
N("036930", "2026-05-12", "+", "trend", "한 달 새 156.74% 급등, 메모리 투자 확대 기대",
  "주성엔지니어링 주가가 2026년 5월 11일 기준 한 달간 156.74% 올라, 같은 기간 코스닥150 정보기술지수 상승률(24.03%)을 크게 웃돌았어요. 삼성전자 평택 P5, SK하이닉스 용인 클러스터 일정 앞당김과 낸드 신규 투자 재개 기대가 장비주 전반을 끌어올린 영향이에요. 회사 고유 실적보다는 메모리 설비투자 사이클 기대가 이 국면 후반 급등을 주도했다는 의미예요.",
  "https://www.hankyung.com/article/2026051295626", "한국경제")
N("039030", "2024-07-15", "-", "earn", "2분기 영업이익 92억 전망, 전년 대비 -24.9%로 기대 하회",
  "상상인증권은 이오테크닉스의 2024년 2분기 매출을 814억원(전년 대비 -6.3%), 영업이익을 92억원(-24.9%)으로 추정하며 시장 기대에 못 미칠 것으로 봤어요. 2024년 연간 매출 전망도 11.2% 낮췄고, 목표가 30만원은 유지했지만 '상반기 부진, 하반기 회복'이라는 시각이었어요. 2024년 4월 고점 이후 하락 국면에서 실적 눈높이가 내려간 근거가 된 리포트예요.",
  "https://www.asiae.co.kr/en/article/2024071508111279936", "아시아경제")
# ---- 에프에스티(036810)
N("036810", "2024-04-26", "+", "cat", "EUV 펠리클 전용 공장 190억 투자, 연간 1500억 신규 매출 기대",
  "에프에스티가 2024년 4월 26일 장중 4.21% 올라 3만2200원에 거래됐어요. 약 190억원을 들여 EUV 펠리클 전용 공장을 착공했고 하반기 완공 후 연내 시양산품 공급, 2025년 본격 양산을 계획한다는 소식이 부각됐어요. 신규 수요 1.5만장·장당 1000만원 가정 시 연간 약 1500억원 신규 매출이 가능하다는 추정이 나오며, 2024년 6월 고점까지의 상승을 EUV 펠리클 국산화 기대가 이끌었다는 의미예요.",
  "https://view.asiae.co.kr/article/2024042611402219741", "아시아경제")
N("036810", "2026-04-06", "+", "news", "유안타, 2026년 영업이익 231억·2027년 371억 전망",
  "유안타증권은 에프에스티의 2026년 칠러 매출을 1240억원(+11.3%), 소재 부문을 1885억원(+13.3%), 이 중 펠리클을 1300억원(+17.5%)으로 전망했어요. 연결 영업이익은 2026년 231억원(이익률 7.5%), 2027년 371억원(10.5%)으로 봤고, EUV CNT 펠리클 수율이 안정되면 2000억~3000억원의 추가 매출 여력이 있다고 했어요. 2026년 1월 고점 이후 하락 국면에서도 ArF 펠리클 지배력과 EUV 확장 기대는 유지되고 있었다는 의미예요.",
  "https://core.asiae.co.kr/article/2026040607481966519", "아시아경제")
N("039030", "2026-03-31", "+", "cat", "주총서 '사상 최대 실적' 자신, 2025년 영업이익 808억(+159%)",
  "이오테크닉스 성규동 회장이 2026년 3월 31일 정기주총 후 올해 실적이 전년보다 큰 폭으로 늘어 사상 최대치를 넘을 것이라며 매출 17% 이상 성장을 자신했어요. 2025년 실적은 매출 3809억원(약 +19%), 영업이익 808억원(약 +159%)이었고, 연말 안성 공장이 완공되면 생산능력이 2배가 된다고 밝혔어요. 2025년 4월 저점 이후 상승 국면에서 경영진이 성장 가이던스로 눈높이를 끌어올린 사건이에요.",
  "https://zdnet.co.kr/view/?no=20260331161227", "지디넷코리아")
# ---- 성도이엔지(037350)
N("037350", "2026-02-09", "+", "news", "삼성·SK 신공장 투자 재개에 클린룸 수주 준비 본격화",
  "성도이엔지는 2026년 메모리 가격 상승을 배경으로 반도체 기업들의 신공장 설비 투자가 본격화될 것으로 보고, 입찰을 통해 수주를 늘릴 것으로 기대한다고 밝혔어요. 삼성전자는 평택 5공장 공사에 착수하고 4공장 2단계를 첨단 메모리 라인으로 바꿔 건설을 재개했고, SK하이닉스는 용인 클러스터 1기 팹 가동을 목표로 하고 있어요. 2026년 4월 고점까지 이어진 상승 국면 후반을 클린룸 수주 기대가 받쳤다는 의미예요.",
  "https://www.etoday.co.kr/news/view/2554076", "이투데이")
N("036810", "2026-08-17", "+", "earn", "2분기 영업이익 96억, 전년 17억의 5.6배",
  "에프에스티의 2026년 2분기 매출은 893억원(전년 대비 약 +17.5%), 영업이익은 96억원으로 전년 동기 17억원의 약 5.6배였고 이익률이 약 10.8%로 올랐어요. 1분기 영업이익 14억원(이익률 약 2.0%) 부진에서 반등하며 상반기 영업이익 110억원(약 +145%), 순이익 42억원으로 흑자 전환했어요. 2025년 R&D·칠러 해외 지원·미국 테일러공장 납품 준비 등 선투자 부담이 걷히고 영업레버리지가 나타났다는 해석으로, 2026년 7월 저점 이후 반등 국면의 실적 근거예요.",
  "https://www.kharn.kr/mobile/article.html?no=31597", "한국재경신문")
# ---- 아이에이(038880)
N("038880", "2025-01-06", "+", "cat", "김동진 회장 지분 7.85% 디씨이에 200억 매각, 종가 대비 178.6% 프리미엄",
  "아이에이 최대주주 김동진 회장이 보유 지분 7.85%(2475만주) 전부를 2대주주 디씨이에 약 200억원, 주당 808원에 넘기기로 했어요. 이는 1월 6일 종가 290원보다 178.6% 높은 가격으로 경영권 프리미엄이 반영됐고, 디씨이 지분은 6.52%에서 14.37%로 늘어나요. 같은 날 디씨이 등을 대상으로 주당 207원, 약 125억원 규모 3자배정 유상증자도 결정돼, 2024년 11월부터 이어진 단기 급등 국면의 고점 무렵 경영권 교체 이벤트였어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/69268", "스마트투데이")
N("038880", "2025-03-18", "-", "cat", "195억 CB 발행해 티맥스 IaaS 사업부 286억 인수",
  "아이에이 자회사 아이에이클라우드가 2025년 2월 티맥스에이앤씨 IaaS 사업부를 286억원에 인수했고, 자금 마련을 위해 아이에이가 195억원 규모 전환사채(CB)를 발행해 이 중 50억원을 캑터스PE가 인수했어요. 회사는 2030년 국내 IaaS 점유율 30%, 영업이익 300억원을 목표로 내세웠어요. 신사업 전환 과정에서 CB 등 잠재 물량이 늘어난 것으로, 2025년 1월 고점 이후 -80% 하락 국면 초반의 사건이에요.",
  "https://v.daum.net/v/20250318092802738", "다음(마켓인사이트)")
N("037350", "2025-08-28", "+", "cat", "엠에스씨 양산3공장 953억 수주, 매출의 9.54%",
  "성도이엔지가 2025년 8월 28일 엠에스씨와 경남 양산3공장 신축 프로젝트 953억5000만원 규모 계약을 맺었다고 공시했어요. 2024년 연결 매출(약 9996억원)의 9.54%에 해당하고 계약 기간은 2026년 1월부터 2027년 11월까지예요. 2024년 3월 저점 이후 상승 국면에서 반도체 외 비전방 수주로 일감을 채운 사례예요.",
  "https://www.digitaltoday.co.kr/aigongsi/amp/2161/seongdo-eng-msc-contract", "디지털투데이")
