# notes semi 05
# ---- 텔레칩스(054450)
N("054450", "2026-05-13", "-", "news", "2025년 무형자산 손상 571억, 순손실 616억",
  "텔레칩스는 2025년 무형자산 손상차손 570억7000만원(전년 103억6000만원의 약 5.5배)을 반영해 연간 순손실이 616억3000만원으로 커졌어요. 2026년 1분기에는 매출 660억8000만원(+46.2%), 영업이익 61억원으로 흑자전환했지만, 개발비 자산이 총자산의 30.2%(1108억원)로 추가 손상 부담이 남아 있다는 지적이 나왔어요. 하락 국면에서 대규모 손상과 적자 확대가 주가를 누른 회사 고유 요인이었어요.",
  "https://v.daum.net/v/20260513060055209", "IB토마토")
# ---- 리노공업(058470)
N("058470", "2026-04-23", "+", "earn", "2025년 매출 3725억·영업이익 1770억 사상 최대, 연초 대비 +85%",
  "리노공업은 2025년 연결 매출 3725억원(+33.9%), 영업이익 1770억원(+42.5%), 영업이익률 47.5%로 사상 최대 실적을 냈어요. 4월 22일 종가 12만200원으로 연초(6만4900원) 대비 85.2% 올라 코스닥 시총 6위에 올랐고, AI 반도체·TSMC WMCM 패키징 확대에 따른 미세 피치 소켓 수요와 2000억원 규모 부산 신공장(생산능력 약 4500억→9500억원) 기대가 반영됐어요. 2024년 11월 이후 상승 국면의 정점 부근에서 실적 신기록과 증설 기대가 주가를 끌어올린 셈이에요.",
  "https://v.daum.net/v/20260423060238327", "조선비즈")
# ---- 티씨케이(064760)
N("064760", "2026-01-26", "+", "news", "4분기 실적 미달에도 상반기 호실적 기대에 +8.4%, 목표가 22만원",
  "티씨케이는 2025년 4분기 매출 722억원(컨센서스 812억원), 영업이익 203억원(컨센서스 230억원)으로 기대에 못 미쳤지만, 이연된 매출이 2026년 1분기에 인식되며 매출 841억원·영업이익 252억원이 예상된다는 분석이 나왔어요. 1월 26일 주가는 8.38% 오른 19만6500원을 기록했고 신한투자증권은 목표가를 22만원으로 올렸어요. NAND V9 전환·가동률 회복 기대가 2024년 11월 이후 상승 국면을 이어가게 한 요인이었어요.",
  "https://view.asiae.co.kr/en/article/2026012614171857622", "아시아경제")
N("058470", "2026-10-12", "-", "earn", "62일 전면 파업에 3분기 영업이익 컨센서스 26% 하회 전망",
  "SK증권은 리노공업의 2026년 3분기 매출을 855억원, 영업이익을 385억원으로 추정했는데, 이는 컨센서스(매출 1074억원·영업이익 522억원)를 각각 20%, 26% 밑도는 수준이에요. 전년 대비로도 매출 -12%, 영업이익 -20% 감소로, 62일간 이어진 전면 파업과 환율 약세가 주요 원인으로 꼽혔어요. 2026년 4월 고점 이후 하락 국면에서 파업에 따른 실적 훼손이 회사 고유 악재로 작용했어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/112501", "스마트투데이")
# ---- 인텍플러스(064290)
N("064290", "2026-01-19", "+", "news", "4분기 흑자전환 전망·CoWoS 검사장비 수주 기대, 목표가 1만8000원",
  "상상인증권은 인텍플러스의 2025년 4분기 매출을 361억원(+47.4%), 영업이익 76억원으로 흑자전환할 것으로 보고 목표가를 1만8000원으로 올렸어요. 2026년 하반기 대만 OSAT의 CoWoS 검사장비, 일본 기판업체의 FC-BGA 검사장비, 북미 IDM의 대면적 기판 검사장비 수주가 기대되고, 연간 매출 1031억원(+20.5%)·영업이익 75억원(흑자전환)이 전망됐어요. 2025년 3월 이후 상승 국면에서 첨단 패키징 검사장비 수주 기대가 재평가 근거가 됐어요.",
  "https://core.asiae.co.kr/article/2026011907571026475", "아시아경제")
N("058470", "2026-07-23", "-", "cat", "이채윤 회장 9.18% 블록딜 후 부진, 노조 무기한 총파업",
  "리노공업 이채윤 회장은 6월 12일 보유 주식 700만주(지분 약 9.18%)를 블록딜로 매각해 지분율이 34.66%에서 25.48%로 낮아졌어요. 주가는 4월 23일 장중 고점 12만9000원 이후 반등 없이 밀려 7월 23일 종가 7만3900원으로 고점 대비 약 42.7% 떨어졌고, 같은 날 노조가 무기한 총파업에 들어갔어요. 최대주주 지분 매각과 파업이 2026년 4월 이후 하락 국면을 주도한 회사 고유 악재였어요.",
  "https://www.wikitree.co.kr/articles/1148100", "위키트리")
N("054450", "2024-12-27", "+", "news", "고객사 확대·고정비 축소 기대에 +3%, NH '실적 가시성 최고'",
  "NH투자증권은 텔레칩스가 고객사 확대로 매출이 늘고, 2025년 하반기부터 개발을 마친 칩이 양산되며 고정비 부담이 줄어드는 국면에 들어설 것으로 봤어요. 2024년 매출은 1846억원(-3.4%), 영업이익 36억5000만원(-78.2%)으로 부진이 예상됐지만, 12월 27일 주가는 2.99% 오른 1만3080원을 기록했어요. 2024년 11월 저점 이후 반등 국면 초입에서 2025~2026년 실적 개선 기대가 부각된 사례예요.",
  "https://view.asiae.co.kr/article/2024122710074085382", "아시아경제")
# ---- 미코(059090)
N("059090", "2026-03-10", "+", "earn", "HPS 편입 효과로 2025년 매출 9768억(+80.7%), 부채비율 220%",
  "미코는 2025년 현대중공업파워시스템(HPS) 지분 70%를 확보해 연결 편입하면서 2025년 매출이 9768억원으로 80.7% 늘었고, 영업이익은 1018억원(+7.6%), 순이익 731억원(-4.4%)을 기록했어요. 다만 인수 영향으로 부채총계가 8598억원에서 1조5583억원으로 늘어 부채비율이 161%에서 220%로 높아졌어요. 2024년 11월 이후 상승 국면에서 M&A로 외형이 1조원 가까이 커진 것이 핵심 변화였어요.",
  "https://newstomato.com/ReadNews.aspx?no=1293452", "IB토마토")
N("059090", "2026-05-04", "+", "cat", "자회사 미코하이테크 흡수합병 결정에 +15.2%",
  "미코는 자회사 미코하이테크를 흡수합병하는 소규모 합병을 공시했고, 효율성·시너지 기대에 5월 4일 주가가 15.23% 오른 2만6100원(시총 8722억원)에 마감했어요. 같은 날 코스닥 반도체 장비 업종도 8.08% 올라 업황 강세가 겹쳤어요. 사업구조 단순화가 2024년 11월 이후 상승 국면에 추가 동력이 된 사례예요.",
  "https://news.jkn.co.kr/post/902168", "재경일보")
N("058470", "2026-04-27", "-", "cat", "최대주주 이채윤 대표 700만주(9.18%) 매각 공시에 -14.4%",
  "리노공업 최대주주 이채윤 대표가 4월 24일 보통주 700만주(지분 9.18%)를 5월 26일~6월 24일 시간외매매로 처분하겠다고 공시했어요. 4월 23일 종가 12만3300원 기준 약 8631억원 규모로, 4월 27일 오전 주가는 14.39% 급락한 10만6500원을 기록했어요. 사상 최고가 직후 나온 대주주 대규모 매각이 2026년 4월 이후 하락 국면의 출발점이 됐어요.",
  "https://www.ajunews.com/view/20260427094852450", "아주경제")
N("058470", "2024-11-14", "-", "earn", "3분기 컨센서스 하회, 목표가 29만→22만원(-24%)에 -5%",
  "삼성증권은 리노공업의 2024년 3분기 실적이 컨센서스를 밑돌았다며 목표가를 29만원에서 22만원으로 24.1% 내렸어요. 주요 고객사 양산 소켓 판매 회복이 늦어 매출 성장이 정체됐고, 내년 매출 성장률 전망도 15%에서 8%로 낮췄어요. 발표 후 11월 14일 주가는 5% 넘게 떨어졌고, 2024년 5월 이후 하락 국면의 마무리 단계에서 성장 정체 우려를 확인시킨 실적이었어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/64486", "스마트투데이")
N("064760", "2023-11-23", "+", "news", "키움 '4분기 영업이익 197억(+32%) 기대 상회 전망', 목표가 13만원",
  "키움증권은 티씨케이의 2023년 4분기 매출을 613억원(전분기 +14%), 영업이익을 197억원(+32%)으로 추정하며 시장 예상을 웃돌 것으로 봤어요. 삼성전자 시안 공장 가동률 상승과 8세대 V-NAND 생산 확대로 SiC 링 판매가 늘 것으로 보고 2024년 매출 2820억원(+25%)·영업이익 1012억원(+45%)을 전망했고, 목표가 13만원과 매수 의견을 유지했어요. 메모리 감산 바닥에서 업황 회복 수혜 기대가 2023년 10월 이후 상승 국면을 연 계기였어요.",
  "https://view.asiae.co.kr/article/2023112308545414802", "아시아경제")
N("054450", "2023-11-27", "+", "cat", "테슬라 FSD v12 기대에 자율주행 팹리스 테마 편입, 3분기 영업이익 +59%",
  "테슬라 FSD 12 버전 기대감으로 칩스앤미디어·가온칩스와 함께 자율주행 팹리스 3인방으로 묶이며 11월 27일 오전 텔레칩스 주가가 3.22% 올랐어요. 텔레칩스의 2023년 3분기 매출은 525억원(+34.5%), 영업이익은 65억원(+59.3%)으로 차량 인포테인먼트 AP 판가 상승 효과를 봤고, AI 알고리즘 자회사와 개발한 ADAS 칩이 2024년 말부터 실적에 기여할 것이란 전망이 나왔어요. 실적 성장과 자율주행 테마가 2023년 상승 국면의 막바지를 끌어올린 요인이었어요.",
  "https://v.daum.net/v/20231127115733955", "머니투데이")
# ---- 티엘아이(062860)
N("062860", "2022-06-29", "-", "news", "두 달 새 최대주주 3번 교체 경영권 분쟁, 매출 6년 새 -77%·2년 연속 적자",
  "티엘아이는 창업자 김달수 전 대표와 조상준 전략기획 부사장 측 주주연대·소액주주가 맞서며 2022년 4~6월 두 달 사이 최대주주가 세 번 바뀌었고, 7월 7일 임시주총에서 경영권 향방이 결정될 예정이었어요. 분쟁 대상은 3월 말 기준 약 270억원의 현금성 자산이었고, 매출은 2015년 1327억원에서 2021년 308억원으로 76.78% 줄어 2년 연속 영업적자를 냈어요. 본업 부진 속 경영권 분쟁이 2022년 5월 이후 장기 하락 국면의 출발점에 놓인 회사 고유 이슈였어요.",
  "https://www.etoday.co.kr/news/view/2148513", "이투데이")
N("064760", "2025-06-12", "+", "news", "램리서치 점유율 하락 우려 해소, 키움 목표가 11만→13만원",
  "키움증권은 TEL의 극저온 에칭 장비 성능이 기대에 못 미치면서 티씨케이 주요 고객인 램리서치의 점유율 하락 우려가 해소됐다며 목표가를 11만원에서 13만원으로 올렸어요. 중국 YMTC의 대규모 증설, 삼성전자 NAND 공장 가동률 상승, 반도체용 흑연의 중국 매출 비중 확대를 근거로 2026~2027년 실적 전망도 높였어요. 중장기 할인 요인이던 경쟁 장비 우려가 걷힌 것이 2024년 11월 이후 상승 국면의 재평가 근거가 됐어요.",
  "https://www.hankyung.com/article/2025061294296", "한국경제")
N("064760", "2022-10-20", "-", "news", "3분기 영업이익 351억(+31.8%) 호실적에도 멀티플 하락, 목표가 16만→13만원",
  "티씨케이는 2022년 3분기 매출 822억원(+19.6%), 영업이익 351억원(+31.8%)으로 호실적을 냈지만, IBK투자증권은 반도체 업황 둔화로 업종 멀티플이 낮아졌다며 목표가를 16만원에서 13만원으로 내렸어요. 전일 종가는 10만500원으로 실적 전망과 주가가 반대로 움직이고 있다는 평가가 나왔어요. 사상 최대 실적에도 업황 하강에 따른 밸류에이션 축소가 2021년 6월 이후 하락 국면을 이어가게 했어요.",
  "https://edaily.co.kr/News/Read?mediaCodeNo=257&newsId=01354646632494888", "이데일리")
N("064290", "2023-04-28", "+", "cat", "353억 이차전지 검사장비 수주, 전년 매출의 29.7%",
  "인텍플러스는 4월 20일 이차전지 외관검사 시스템과 배터리 핸들러 시스템 각 176억원, 총 353억원 규모의 공급계약을 맺었다고 밝혔어요. 계약 규모는 전년 매출의 약 29.7%에 달했고, 거래 상대방은 영업비밀 보호를 이유로 공개하지 않았어요. 2022년 12월 이후 상승 국면에서 반도체 검사장비 회사가 이차전지 장비 수주로 성장 기대를 키운 대형 계약이었어요.",
  "https://www.mt.co.kr/industry/2023/04/28/2023042810172044614", "머니투데이")
N("064290", "2024-10-28", "-", "earn", "3분기 매출 컨센서스 16% 하회·적자 확대 전망, 목표가 4만4000→2만4000원",
  "LS증권은 인텍플러스의 2024년 3분기 매출을 235억원으로 컨센서스(279억원)보다 약 16% 낮게, 영업손실은 34억원으로 컨센서스(-17억원)의 두 배 수준으로 추정했어요. 고객사 투자 축소로 반도체 부문이 부진하다며 목표가를 4만4000원에서 2만4000원으로 45% 내렸고, 2024년 연간 영업손실은 약 101억원으로 전망했어요. 2023년 7월 고점 이후 하락 국면에서 적자 확대가 주가를 끌어내린 핵심 요인이었어요.",
  "https://www.newsis.com/view/NISX20241028_0002935835", "뉴시스")
# ---- 하나마이크론(067310)
N("067310", "2024-05-17", "-", "cat", "1,125억원 유상증자 공시 후 2거래일 -13.6%",
  "하나마이크론이 5월 17일 신주 500만주, 약 1,125억원 규모 주주배정 유상증자(시설 687억·채무상환 250억·운영 188억원)를 공시했어요. 차입금이 1분기 1조원을 넘고 부채비율이 241%까지 오른 가운데 나온 증자여서 주가는 5월 17일 2만6,450원에서 20일 2만2,850원으로 13.61% 떨어졌어요. 영업이익률이 2021년 15.7%에서 2023년 6.0%로 낮아진 상황의 재무 부담이 하락 국면을 키운 요인이었어요.",
  "https://newstomato.com/ReadNews.aspx?no=1230757", "IB토마토")
N("067310", "2026-09-22", "+", "news", "후공정 외주 확대 기대에 한 주간 +30.2%",
  "9월 21일까지 한 주 동안 하나마이크론 주가가 30.23% 올랐어요. 메모리 대기업들이 범용 메모리의 테스트·패키징을 외주로 돌리면서 후공정 업체가 수혜를 본다는 기대가 컸고, 같은 기간 외국인이 558억원을 순매수했어요. 진행 중인 상승 국면에서 AI 수요 재점화와 외주 확대가 주가를 끌어올린 장면이에요.",
  "https://www.mt.co.kr/article/2026092215234069115", "머니투데이")
# ---- 원익QnC(074600)
N("074600", "2024-11-27", "-", "earn", "4Q 영업이익 192억원 컨센서스 하회 전망, 목표가 4.15만→2.8만원",
  "키움증권은 원익QnC의 4분기 매출을 2,202억원(-2% YoY), 영업이익을 192억원(-36%)으로 추정해 컨센서스(매출 2,277억원·영업이익 203억원)를 밑돌 것으로 봤어요. 목표주가는 4만1,500원에서 2만8,000원으로 크게 낮췄고 26일 종가는 2만300원이었어요. 단기 실적 둔화가 불가피하다는 평가가 하락 국면을 뒷받침했어요.",
  "https://www.asiae.co.kr/en/article/2024112707534011317", "아시아경제")
N("074600", "2026-03-06", "+", "earn", "4Q 흑자전환·고객 재고 확대 지시에 장중 +13.2%",
  "3월 6일 원익QnC 주가가 장중 13.19% 오른 3만4,750원에 거래됐어요. 지난해 4분기 매출 2,491억원(+14.7% YoY), 영업이익 184억원으로 흑자전환했고, 유안타증권은 북미 고객사가 핵심 부품 재고를 두 배 이상 늘리라고 지시했다며 1분기 영업이익 247억원, 올해 1,124억원(+88.6%)을 전망했어요(목표가 4만1,000원). 메모리 증설 재개로 상승 국면이 본격화한 계기였어요.",
  "https://www.asiae.co.kr/en/article/2026030613504454532", "아시아경제")
N("074600", "2026-05-12", "+", "earn", "1Q 영업이익 219억원 기대 11% 하회에도 목표가 4.5만→6만원",
  "원익QnC의 1분기 영업이익은 219억원으로 시장 기대를 11% 밑돌았지만 전년 대비 15% 늘었어요. 신한투자증권은 소부장 최선호주로 꼽으며 목표주가를 4만5,000원에서 6만원으로 올렸고, 올해 세 번째 상향이었어요. 단기 실적 미스보다 증설 사이클 기대가 우세했던 국면이에요.",
  "https://www.asiae.co.kr/en/article/2026051215262574543", "아시아경제")
# ---- 덕산하이메탈(077360)
N("077360", "2023-05-26", "+", "news", "엔비디아 깜짝 실적에 AI 솔더볼 수혜 기대 +3.5%",
  "엔비디아가 1분기 매출 71.9억달러(예상 65.2억달러)와 2분기 매출 가이던스 110억달러(예상 71.5억달러)를 내놓자, 마이크로솔더볼 세계 1위인 덕산하이메탈이 장중 3.48% 오른 6,240원에 거래됐어요. CPU·GPU 등 고성능 칩에 쓰이는 MSB 공급 증가 기대가 부각됐어요. AI 칩 수혜주로 묶이며 2023년 상반기 상승 국면을 이끈 재료였어요.",
  "https://view.asiae.co.kr/article/2023052609141975768", "아시아경제")
N("077360", "2025-11-17", "+", "news", "은·주석 급등 부담에 SK하이닉스와 원자재 가격 연동 합의",
  "주석 가격이 약 20%, 은 가격이 약 50% 오르며 원가의 약 60%를 차지하는 금속 부담으로 수익성이 크게 떨어졌지만, 덕산하이메탈은 삼성전자에 이어 SK하이닉스와도 내년 2분기부터 원자재 가격을 판매가에 연동하기로 합의했다고 밝혔어요. AI 서버·전장용 고신뢰성 합금과 TSMC·마이크론 공급망 진입을 목표로 내세웠어요. 원가 부담 해소 기대가 상승 국면 후반의 근거가 됐어요.",
  "https://v.daum.net/v/20251117170738265", "한국경제")
N("077360", "2025-12-08", "+", "news", "기판 호황 수혜, 내년 영업이익 224억원(+46%) 전망",
  "하나증권은 덕산하이메탈이 내년 패키지 기판 업황 호조의 수혜를 받아 매출 1,418억원(+22%), 영업이익 224억원(+46%)을 낼 것으로 전망했어요. 솔더볼·코어솔더볼 생산능력을 약 30%, 마이크로솔더볼을 약 10% 늘리고 증설분은 내년 2분기부터 실적에 기여할 것으로 봤어요. 상승 국면에서 증설과 실적 성장 기대가 주가를 받친 근거예요.",
  "https://core.asiae.co.kr/article/2025120807292057415", "아시아경제")
N("077360", "2026-05-29", "-", "cat", "검찰, 반도체 소재 담합 의혹 압수수색",
  "서울중앙지검 범죄수익환수부가 반도체 소재 납품 가격과 공급 물량을 담합한 의혹으로 엠케이전자·엘티메탈·덕산하이메탈 3곳을 압수수색했어요. 세 회사는 SK하이닉스의 핵심 벤더로 소개됐어요. 5월 초 고점 이후 이어진 하락 국면에서 이 사건이 투자심리를 크게 꺾은 악재였어요.",
  "https://view.asiae.co.kr/article/2026052909502637795", "아시아경제")
# ---- 제우스(079370)
N("079370", "2024-08-07", "+", "cat", "美 펄스포지와 포토닉 디본딩 장비 협력에 +8.6%",
  "제우스가 미국 펄스포지와 포토닉 디본딩 자동화 장비 공동개발 전략적 파트너십을 맺었다는 소식에 장중 8.55% 오른 1만2,690원에 거래됐어요. 개발 장비는 국내 주요 반도체 팹에 납품할 예정이며 4분기 화성 연구소 클린룸에 데모기를 설치할 계획이라고 했어요. 하락 국면 중 일시적 반등을 만든 재료였어요.",
  "https://view.asiae.co.kr/article/2024080711023928429", "아시아경제")
N("079370", "2025-01-02", "+", "cat", "삼성 레인보우로보틱스 최대주주 등극에 로봇주로 +4.6%",
  "삼성전자가 콜옵션을 행사해 레인보우로보틱스 최대주주(35%)가 되면서 관련 로봇주에 관심이 쏠렸고, 제우스는 장중 4.55% 오른 1만2,420원에 거래됐어요. 제우스는 다관절 로봇 ZERO 등 로봇 사업 확장이 부각됐어요. 반도체 장비주가 로봇 테마로 묶이며 상승 국면 초반의 동력이 됐어요.",
  "https://www.asiae.co.kr/en/article/2025010210350776012", "아시아경제")
N("079370", "2025-08-14", "+", "earn", "HBM 세정장비로 상반기 별도 영업이익률 15.1%",
  "제우스의 상반기 별도 매출은 1,248억원으로 1.78% 줄었지만 영업이익은 189억원으로 영업이익률이 지난해 상반기 6.49%에서 15.1%로 뛰었어요. HBM 제조에 중요한 TSV 세정 등 첨단 패키징 세정장비가 주요 메모리사에 공급되며 수익성을 끌어올렸어요(연결 매출 1,977억원·영업이익 277억원). HBM 장비 수익성이 상승 국면을 뒷받침한 실적 근거예요.",
  "https://www.mt.co.kr/stock/2025/08/14/2025081416359616427", "더벨(머니투데이)")
# ---- 제주반도체(080220)
N("080220", "2024-03-28", "+", "news", "두 달 조정 뒤 온디바이스 AI 기대에 장중 +12.6%",
  "제주반도체는 1월 25일 장중 3만8,550원 고점을 찍은 뒤 단기 급등에 따른 차익실현으로 두 달 가까이 조정받아 전날 2만3,000원까지 내려왔어요. 3월 28일에는 온디바이스 AI 기대와 대형 메모리사의 레거시 감산 수혜 전망으로 장중 12.63% 오른 2만6,300원에 거래됐어요. 장기 상승 국면 막바지의 반등이었고, 이후 하락 국면으로 넘어갔어요.",
  "https://core.asiae.co.kr/article/2024032811021278867", "아시아경제")
N("080220", "2025-09-23", "+", "news", "LPDDR4X 공급 부족·가격 인상 수혜 기대, 2만원대",
  "주요 공급사의 LPDDR4X 감산·라인 중단과 관세 선수요가 겹쳐 저전력 D램 공급이 부족해지자 제주반도체가 수혜주로 부각돼 2만50원(+1.16%)에 거래됐어요. 상반기 별도 매출은 980억원으로 전년 대비 15% 늘었어요. 범용 저전력 메모리 가격 상승이 진행 중인 상승 국면의 핵심 동력이었어요.",
  "https://v.daum.net/v/20250923093911317", "아시아경제")
N("080220", "2025-02-14", "+", "news", "반도체 특별법·AI 반도체 지원 기대에 장중 9%대 상승",
  "반도체 특별법의 주 52시간 예외 특례 논의와 정부의 1조원 규모 토종 AI 반도체 지원사업 소식에 어보브반도체 등 중소형 반도체주가 오르며 제주반도체도 장중 9%대 상승했어요. 정책 기대가 소형 메모리 팹리스로 번진 흐름이었어요. 2024년 11월 저점 이후 상승 국면 초기의 테마성 매수였어요.",
  "https://view.asiae.co.kr/article/2025021409304624942", "아시아경제")
N("080220", "2025-11-13", "+", "earn", "3Q 매출 1,088억원(+197%)·영업이익 140억원(+762%) 사상 최대",
  "제주반도체의 3분기 매출은 1,088억원으로 전년 대비 197%, 영업이익은 140억원으로 762% 늘어 모두 분기 사상 최대를 기록했어요. 3분기 D램 가격이 약 30% 오르고 환율이 상승한 덕분이며, 3분기 누적 매출 2,083억원은 지난해 연간(1,623억원)을 넘었어요. 메모리 가격 급등이 실적으로 확인되며 상승 국면을 굳힌 발표였어요.",
  "https://v.daum.net/v/20251113174749532", "파이낸셜뉴스")
# ---- 오킨스전자(080580)
N("080580", "2023-12-15", "+", "cat", "CXL 테마 편입, 이틀 연속 상한가(+68.9%)",
  "삼성전자의 차세대 메모리 기술 CXL 확대 소식에 DDR5 메모리용 인터페이스를 개발한 오킨스전자가 CXL 관련주로 묶이며 이틀 연속 상한가를 기록했어요. 주가는 12일 3,955원에서 14일 6,680원으로 이틀 만에 68.9% 올랐어요. 2023년 10월 저점에서 시작된 +223% 급등 국면을 주도한 테마성 촉매였어요.",
  "https://v.daum.net/v/20231215063026227", "다음뉴스(아시아경제)")
N("080580", "2024-04-02", "-", "earn", "2023년 영업이익 3.7억원(-85.7%), 이자보상배율 0.10배",
  "오킨스전자의 2023년 매출은 569억원으로 11.4% 줄었고 영업이익은 3억7,428만원으로 전년 26억922만원보다 85.7% 급감했어요. 주력 반도체 검사용 소켓 매출이 7.62% 줄고 판관비가 103억원에서 111억원으로 늘어 이자보상배율이 0.10배까지 떨어지며 좀비기업 우려가 제기됐어요. CXL 테마로 2024년 초 1만원대까지 올랐던 주가가 3월 28일 8,950원으로 밀린 가운데, 부진한 실적 확인이 2024년 1~11월 -63% 하락 국면의 배경이 됐어요.",
  "https://newstomato.com/ReadNews.aspx?no=1225117", "뉴스토마토(IB토마토)")
N("080580", "2026-01-19", "-", "cat", "자사주 47.7만주 대상 58억원 EB 발행에 주주 반발",
  "오킨스전자는 1월 9일 자사주 476,513주를 교환 대상으로 하는 58억원 규모 사모 교환사채(EB) 발행을 결정했어요. 표면이자 0%, 교환가 1만2,180원, 만기 2031년 1월 19일이며 설비투자 자금 용도였지만, 자사주 소각 기조와 어긋나고 잠재 매도 물량(오버행)이 된다는 주주 반발이 컸어요. 발표 당일 장중 5% 넘게 하락했다는 투자자 주장도 나왔는데, 상승 국면 후반 수급 부담 요인이었어요.",
  "https://news.tf.co.kr/read/economy/2283189.htm", "더팩트")
N("080580", "2025-12-05", "+", "earn", "3Q25 영업이익 37억원 사상 최대, 하루 +16.10%",
  "오킨스전자는 12월 5일 10,240원으로 16.10% 오르며 6개월 하락 끝에 20일 이동평균선을 돌파했어요. 3분기 연결 영업이익이 약 37억원으로 창사 이래 최대 분기 실적이었고, 외국인이 이날 약 21만 주를 순매수했으며 CXL 기대도 재료로 거론됐어요. 사상 최대 실적이 2024년 11월~2026년 4월 +400% 상승 국면 후반부의 재상승을 뒷받침했어요.",
  "https://www.topstarnews.net/news/articleView.html?idxno=15897447", "톱스타뉴스")
N("080580", "2026-08-28", "+", "earn", "2Q26 영업이익 84억원(+163.1%), OPM 23.9%·목표가 2만8,000원 유지",
  "현대차증권은 오킨스전자의 2분기 매출이 351억원(+29.6%), 영업이익이 84억원(+163.1%)으로 영업이익률 23.9%를 기록했다고 분석했어요. 차세대 메모리 테스트 장비 CLT용 번인 소켓 매출이 전분기보다 44%, 커넥터 매출이 79% 늘어난 덕분이었고, 투자의견 매수와 목표주가 2만8,000원을 유지했어요. 내년 예상 실적 기준 PER 8.8배로 저평가라는 평가와 함께, 2026년 7월 저점 이후 +135% 반등 국면을 이끈 실적 확인이었어요.",
  "https://en.edaily.co.kr/news/eda202608285110", "이데일리")
