N("081180", "2026-10-05", "-", "earn", "1H26 매출 -16.7%, 영업손실 77억원으로 확대",
  "쎄크의 2026년 상반기 매출은 172억8,940만원으로 전년 동기보다 16.7% 줄었고, 영업손실은 77억1,788만원으로 전년 동기 41억9,132만원보다 커졌어요. 영업손실의 32.0%인 24억7,256만원이 재고자산평가손실이었고, 재고자산이 총자산의 42.5%에 달했어요. 2025년 말 기대했던 흑자 전환이 무산되고 적자가 커진 것이 2026년 -72% 하락 국면의 배경으로 보여요.",
  "https://economist.co.kr/article/view/ecn202609280040", "이코노미스트")
# ---- 에프엔에스테크(083500)
N("083500", "2023-05-16", "+", "cat", "삼성디스플레이 4.1조 8.6세대 투자 수혜, 목표가 1만2,800원",
  "리서치알음은 삼성디스플레이의 4조1,000억원 규모 투자로 에프엔에스테크가 내년 410억원가량의 매출을 인식할 것으로 보고 목표주가 1만2,800원을 제시했어요. 2022년 매출 676억원·영업이익 58억원에 이어 2023년은 매출 631억원·영업이익 62억원으로 숨 고르기 후 2024년 사상 최대 매출이 기대된다고 했어요. 삼성디스플레이향 대량 수주 기대가 2022년 9월~2024년 6월 +133% 상승 국면의 핵심 재료였어요.",
  "https://newstomato.com/ReadNews.aspx?no=1187797", "뉴스토마토")
N("083500", "2025-09-03", "+", "cat", "대만 아사히램프 62.96% 109억원 인수, 1H25 영업이익 57억원",
  "에프엔에스테크는 2025년 7월 말 TSMC·어플라이드머티어리얼즈에 할로겐 램프를 공급하는 대만 아사히램프 지분 62.96%를 109억원에 인수했어요. 같은 시기 상반기 연결 매출은 429억원(+130%), 영업이익은 57억원(약 +6,133%)으로 삼성디스플레이 133억원 공급계약 효과가 컸어요. 디스플레이 의존에서 반도체 부품 수출로 넓히는 계기가 돼 2024년 12월~2026년 4월 +141% 상승 국면을 뒷받침했어요.",
  "https://dealsite.co.kr/articles/147390", "딜사이트")
N("083500", "2026-03-17", "+", "earn", "2025년 영업이익 105억원(+19.6%), 2026년 192억원 전망·목표가 3만원 유지",
  "SK증권은 에프엔에스테크의 2025년 영업이익이 105억원으로 전년보다 19.6% 늘었다고 짚고, 2026년 영업이익을 192억원(+82.6%)으로 전망하며 목표주가 3만원을 유지했어요. 아사히램프 인수 뒤 비용 효율화와 가동률 상승으로 이익률이 개선됐고 TSMC·SK하이닉스 교차 판매, 하반기 유리기판 신사업도 기대 요인으로 꼽혔어요. 상승 국면 막바지(2026년 4월 고점 직전)에 나온 이익 성장 기대였어요.",
  "https://www.tokenpost.kr/news/market/340148", "토큰포스트")
# ---- GST(083450)
N("083450", "2024-03-12", "+", "news", "AI 서버 액침냉각 부상, 국내 유일 2상형 개발",
  "GST는 2022년 액침냉각 개발을 시작해 2023년 5월 시제품을 공개했고, 1상형을 마친 뒤 국내에서 유일하게 2상형을 개발 중이라고 소개됐어요. 2023년 실적은 매출 약 2,730억원(-12.7%), 영업이익 약 400억원(-29.7%)으로 마이크론향 수출 감소 탓에 줄었지만 2024년 회복이 기대됐어요. AI 데이터센터 냉각 테마가 2024년 4월 고점까지 이어진 상승 국면에 힘을 보탰어요.",
  "https://v.daum.net/v/20240312102259830", "다음뉴스(조선비즈)")
N("083450", "2025-09-22", "+", "news", "칠러 대형 고객 평가 진행, 2025년 영업이익 594억원 전망",
  "GST는 매출의 15%인 칠러 사업에서 대형 반도체 기업 공급 평가가 진행 중이며, 연말부터 수주가 나오면 내년 칠러 비중이 두 배 이상 커질 것으로 기대한다고 밝혔어요. 유안타증권은 2025년 매출 3,497억원, 영업이익 594억원을 전망했고, 석종욱 대표는 중장기 연매출 1조원을 목표로 제시했어요. 칠러·액침냉각이라는 새 성장축이 2024년 11월 이후 +208% 상승 국면의 근거가 됐어요.",
  "https://www.hankyung.com/article/2025092201581", "한국경제")
N("083450", "2026-08-07", "+", "cat", "IBK證 커버리지 개시 목표가 6만5,000원, 2026년 매출 4,000억원 돌파 전망",
  "IBK투자증권은 GST 커버리지를 시작하며 투자의견 매수, 목표주가 6만5,000원을 제시했어요. 10년 가까이 3,000억원을 밑돌던 매출이 올해 4,000억원을 넘고, 1분기 스크러버 단가가 전년보다 13% 오른 대당 약 1억5,000만원, 2026년 스크러버 생산량이 약 2,200대(+23%)로 늘 것으로 봤어요. 주가가 역사적 고점 부근인 상황에서 나온 실적 레벨업 전망으로, 진행 중인 상승 국면을 뒷받침했어요.",
  "https://en.edaily.co.kr/news/eda202608075053", "이데일리")
# ---- 테크윙(089030)
N("089030", "2024-06-25", "+", "cat", "HBM 큐브프로버 기대에 연초 대비 +368%",
  "테크윙 주가는 2023년 말 11,450원에서 2024년 6월 24일 53,600원으로 상장 이래 최고가를 찍으며 연초 대비 368% 올랐어요. 1분기에 HBM 검사장비 '큐브프로버' 개발을 마치고 삼성전자·SK하이닉스·마이크론과 퀄 테스트를 진행 중이라는 점이 핵심 동력이었고, 현대차증권은 목표가 7만원과 2025년 영업이익 1,510억원(2023년 30억원) 가능성을 제시했어요. 2023년 10월부터 계단식으로 오른 이 국면이 HBM 신규 장비 기대감으로 만들어졌다는 걸 보여주는 기사예요.",
  "https://mobile.newsis.com/view/NISX20240625_0002785197", "뉴시스")
N("089030", "2024-12-11", "-", "cat", "큐브프로버 2025년 목표 300대→120~150대 하향",
  "테크윙은 12월 10일 기업설명회에서 2025년 HBM용 큐브프로버 목표 대수를 종전 300대 내외에서 120~150대로 절반 넘게 낮췄어요. 그전부터 고객사 신규 진입 지연 우려로 주가가 하락을 거듭하던 상황이었고, 삼성증권은 단기 실망이 이어질 수 있지만 악재의 끝자락이라고 평가했어요. 큐브프로버 기대가 꺾이며 하락 국면을 굳힌 회사 고유 악재예요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/66867", "스마트투데이")
N("089030", "2025-07-31", "-", "cat", "큐브프로버 퀄 지연에 고점 대비 -60%",
  "녹색경제신문은 테크윙 주가가 7월 30일 27,800원으로 고점 대비 약 60% 떨어졌고 시총이 1조원 수준으로 줄었다고 전했어요. SK하이닉스·마이크론향 큐브프로버 퀄 일정이 늦어지며 올해 100기 이상 공급 전망이 불투명해졌고, 2분기 잠정 영업이익 63억원(전년 동기 대비 -12.9%)도 컨센서스에 못 미쳤어요. 하락 국면 막바지까지 이어진 퀄 지연 실망 매물을 정리한 기사예요.",
  "https://greened.kr/news/articleView.html?idxno=329430", "녹색경제신문")
N("089030", "2026-01-21", "+", "cat", "1월 큐브프로버 수주가 2025년 상반기 전체 상회",
  "테크윙의 2026년 1월 큐브프로버 수주가 2025년 상반기 전체 수준을 넘어선 것으로 전해졌어요. 다만 1월 20일 IR 뒤에는 HBM4 투자 시점 조정으로 4분기 실적(컨센서스 매출 약 460억원, 영업이익 약 70억원)이 기대에 못 미쳤다는 이유로 주가가 크게 밀리기도 했어요. 레거시 메모리 투자 회복과 HBM4 양산에 따른 수주 확대 기대가 상승 국면의 바탕이었다는 걸 보여주는 기사예요.",
  "https://greened.kr/news/articleView.html?idxno=335903", "녹색경제신문")
# ---- 유진테크(084370)
N("084370", "2025-10-20", "+", "cat", "한국투자증권 목표가 50% 상향 10.8만원, 주가 +4.4%",
  "한국투자증권은 유진테크 목표가를 108,000원으로 50% 올리며 D램 공정 전환과 증설이 동시에 일어나는 국면에서 가장 큰 수혜를 볼 업체라고 평가했어요. 발표 당일 주가는 오전 한때 4.43% 오른 84,800원에 거래됐어요. LPCVD 장비가 매출의 절반 넘게 차지하는 구조라 2028년까지 이어질 D램 투자 기대가 상승 국면을 떠받쳤다는 점을 보여줘요.",
  "https://core.asiae.co.kr/article/2025102009203841170", "아시아경제")
N("084370", "2026-06-04", "+", "cat", "소부장 투자심리 개선에 상한가 155,700원(+29.97%)",
  "유진테크는 6월 4일 오전 전일 대비 29.97% 오른 155,700원으로 상한가를 기록했어요. HBM 투자 확대와 선단 공정 전환으로 장비업체 실적 기대가 커졌고, SK증권은 최근 한 달간 소부장 이익 추정치가 상향됐다며 조정을 매수 기회로 봤어요. 상승 국면 막바지 과열 정점에 가까운 급등이었다는 의미가 있어요.",
  "https://v.daum.net/v/6zyePYtWvf?f=p", "아주경제")
# ---- 유니테스트(086390)
N("086390", "2025-06-05", "+", "cat", "SK하이닉스 HBM4 번인테스터 퀄 통과 기대에 상한가",
  "유니테스트는 SK하이닉스 HBM4용 번인테스터 퀄 테스트 중 장비 성능평가 단계를 통과했다는 소식에 6월 5일 장 초반 29.94% 오른 14,020원으로 상한가를 기록했어요. SK하이닉스 HBM4 공급망에 들어가면 매출이 크게 늘 것이라는 기대가 반영됐어요. 2024년 12월부터 이어진 상승 국면의 핵심 촉매가 HBM 장비 진입 기대였다는 걸 보여줘요.",
  "https://www.asiae.co.kr/en/article/2025060509113960109", "아시아경제")
N("086390", "2026-07-23", "+", "cat", "SK하이닉스와 227억원 검사장비 공급계약(매출의 20.6%)",
  "유니테스트는 7월 23일 SK하이닉스와 227억원 규모의 반도체 검사장비 공급계약을 맺었다고 공시했어요. 지난해 연결 매출 1,102억원의 20.6%에 해당하고, 앞서 5월에도 292억원 규모 HBM4 웨이퍼테스터 계약을 따낸 바 있어요. 7월 저점 이후 반등 국면의 출발점이 된 대형 수주예요.",
  "https://view.asiae.co.kr/article/2026072313563463169", "아시아경제")
N("086390", "2026-08-14", "+", "earn", "2분기 영업이익 79억원 흑자전환",
  "유니테스트는 2분기 연결 영업이익 79억원, 순이익 70억원으로 전년 동기·전 분기 대비 모두 흑자전환했다고 8월 14일 발표했어요. HBM용 번인테스터 등 검사장비 매출과 중국·대만·미국 고객사 매출이 늘었고, 태양광 EPC는 부진했지만 수주잔고가 1,000억원을 넘었어요. 실적 저점 통과를 확인시켜 반등 국면을 이어가게 한 발표예요.",
  "https://dealsite.co.kr/articles/167256", "딜사이트")
N("086390", "2025-02-11", "-", "earn", "2024년 영업손실 233억원 적자전환, 매출 -44.9%",
  "유니테스트는 2024년 연결 매출 924억원(전년 대비 -44.9%), 영업손실 233억원, 순손실 241억원으로 적자전환했다고 2월 11일 공시했어요. 회사는 반도체 투자 부진과 태양광 EPC 프로젝트 순연을 매출 감소 원인으로 들었어요. 2024년 하락 국면의 원인이었던 실적 부진이 숫자로 확인된 발표로, 이후 반등은 HBM 장비 기대가 실적 악화를 덮으며 나왔다는 점을 보여줘요.",
  "https://edaily.co.kr/News/Read?mediaCodeNo=257&newsId=04746166642069536", "이데일리")
