  "픽셀플러스는 이미지센서·ISP·AI 칩을 한 패키지에 수직 적층하는 '포토닉 칩렛' 기술을 개발했다는 소식에 5월 8일 오전 23.98% 오른 10,950원에 거래됐어요. 이 기술을 쓴 이미지센서 PX9210K도 출시했어요. 2024년 1월 고점 이후 장기 하락 국면 중 나온 단기 반등 재료였다는 의미예요.",
