# ---- 켐트로닉스(089010)
N("089010", "2024-04-29", "+", "cat", "삼성전기 유리기판 공급망 기술협약 부각에 급등",
  "삼성전기가 유리기판 상용화를 위해 독일 LPKF, LPKF코리아, 켐트로닉스와 기술 협약을 맺고 핵심 공정·장비를 개발한다는 소식에 켐트로닉스 주가가 급등했어요. 유리기판은 기판 시장 판도를 바꿀 신사업으로 주목받던 때였어요. 2024년 5월 고점으로 이어진 상승 국면 막바지의 핵심 테마 촉매예요.",
  "https://www.hankyung.com/article/202404293672i", "한국경제")
N("089010", "2025-03-13", "+", "cat", "유리기판 TGV 풀 밸류체인 부각, 목표가 4만원 신규 제시",
  "현대차증권은 켐트로닉스가 TGV 공정의 풀 밸류체인을 구축해 가공 글래스를 납품할 계획이라며 목표가 4만원을 새로 제시했고, 주가는 3월 13일 오전 5.75% 오른 28,500원을 기록했어요. 2025년 영업이익 430억원, 2026년 600억원을 전망하며 PER 약 13배로 필옵틱스(87배) 등 유리기판주 대비 저평가라고 봤어요. 2024년 11월 저점 이후 상승 국면이 유리기판 테마 재부각과 저평가 논리로 진행됐다는 걸 보여줘요.",
  "https://view.asiae.co.kr/article/2025031309442406068", "아시아경제")
N("089010", "2026-09-04", "-", "cat", "현대차증권 목표가 4.7만원→3.4만원 하향",
  "현대차증권은 켐트로닉스 목표가를 47,000원에서 34,000원으로 낮췄어요. 기존 목표가는 TGV 기대를 반영해 반도체 소재 업체 대비 20% 프리미엄(24.4배)을 줬는데, 패널 식각은 보수적으로 봐야 하고 리지드 OLED 수출 부진과 8.6세대 라인 가동률 미달이 예상된다고 했어요. 2026년 4월 이후 하락 국면에서 유리기판 프리미엄이 걷히고 있음을 보여주는 리포트예요.",
  "https://www.fnnews.com/news/202609040835428393", "파이낸셜뉴스")
