# ---- 후성(093370)
N("093370", "2025-10-27", "+", "cat", "미국 글로벌 업체와 LiPF6 공급계약 소식에 이틀째 급등(+15.8%, 프리마켓 +16%)",
  "후성이 미국 글로벌 업체와 LiPF6(육불화인산리튬) 공급계약을 맺었다는 소식에 전 거래일 15.78% 급등한 데 이어 27일 프리마켓에서도 약 16% 올랐어요. 물량은 국내 생산 캐파의 20~30% 수준으로 ESS향으로 추정되고, 유진투자증권은 3분기 매출 1222억원·영업이익 65억원을 예상하며 목표가 1만원을 유지했어요. 적자였던 LiPF6 사업의 회복 기대가 상승 국면에 불을 붙였어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/94468", "스마트투데이")
N("093370", "2026-06-17", "+", "news", "6월 +53% 급등…WF6 가격 인상·LiPF6 회복, 투자경고 지정",
  "후성 주가는 6월 1일 시초가 1만1470원에서 17일 1만7580원으로 약 53% 올라 유가증권시장 상승률 3위를 기록했고, 외국인이 1~16일 1005억원을 순매수했어요. 중국 텅스텐 수출 통제로 별도 매출의 30% 이상인 WF6 가격이 올랐고, 1분기 별도 영업이익은 83억원(+103%), 2026년 영업이익 컨센서스는 527억원(+107.9%)이었어요. 다만 6월 15일 투자경고 종목 지정 뒤 17일 차익실현으로 8% 넘게 하락해, 상승 국면 고점과 직후 급락의 신호가 됐어요.",
  "https://www.hankyung.com/article/2026061725501", "한국경제")
N("092870", "2025-04-14", "+", "cat", "2024년 매출 -61.6%·적자전환 뒤 삼성 CLT 최종 벤더 선정, 첫 납품",
  "엑시콘의 2024년 매출은 316억원으로 전년 823억원보다 61.6% 줄고 영업이익은 15억9000만원 적자로 전환했어요. 삼성전자가 HBM 투자에 집중하며 D램 테스터 수요가 줄어든 탓이었어요. 다만 2024년 말 삼성전자 CLT(챔버형 저주파 테스터) 퀄테스트를 통과해 최종 벤더가 됐고, 2025년 2분기 대당 42억원 규모 첫 납품이 이뤄지며 이후 상승 국면의 핵심 촉매가 됐어요.",
  "https://dealsite.co.kr/articles/139734", "딜사이트")
N("089970", "2026-02-24", "+", "cat", "SK하이닉스에 463억원 식각장비 공급계약(2024년 매출의 약 65%)",
  "브이엠이 SK하이닉스와 약 463억원 규모 반도체 제조장비 공급계약을 체결했다고 공시했어요. 2024년 매출 702억원의 약 65%에 해당하는 규모이고, 흥국증권은 2026년 매출 2601억원, 영업이익 728억원을 전망했어요. 고객사 증설에 따른 대형 수주가 이어지며 상승 국면 후반부를 떠받쳤어요.",
  "https://v.daum.net/v/20260224161039355", "다음(한국경제)")
