  "KEC가 시설자금·운영자금 마련을 위해 1190억원 규모 유상증자(신주 5600만주, 예정 발행가 2125원)를 결정하자 주가가 장중 13.47% 내린 2505원까지 떨어졌어요. 대규모 신주 발행에 따른 지분 희석 우려가 컸어요. 2021년 말부터 이어진 장기 하락 국면에서 수급 부담을 키운 회사 고유 악재였어요.",
