  "ISC의 2026년 2분기 매출은 729억원으로 분기 최대를 기록하며 전년 대비 41% 늘었고, 영업이익은 213억원으로 55% 증가했어요(영업이익률 29%). AI향 매출이 591억원으로 71% 늘며 전체의 81%를 차지했어요. AI 테스트 소켓 수요가 실적으로 이어진 것이 2024년 7월 이후 상승 국면을 뒷받침했어요.",
