N("094360", "2024-07-30", "-", "earn", "2분기 영업익 6억(-66.5%) 부진에 52주 신저가",
  "칩스앤미디어의 2024년 2분기 매출은 60억5000만원으로 전년 대비 10.9% 줄었고 영업이익은 6억2900만원으로 66.5% 급감했어요. 실적 발표 뒤 주가가 급락해 52주 신저가를 기록했고, 회사는 같은 날 30억원 규모 자사주 취득 신탁 계약(6개월)을 맺었어요. 기대에 못 미친 실적이 2023년 12월 고점 이후 하락 국면을 깊게 만든 계기였어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/56293", "스마트투데이")
N("093520", "2026-02-06", "+", "cat", "65억 자사주 30만주 매입, 2025년 영업익 325억 추정",
  "매커스가 2026년 1월 29일 약 65억원을 들여 자사주 30만주를 장내 매입하겠다고 공시했어요(2월 2일~4월 28일). 2025년 7월 첫 200만주 소각에 이어 올해도 200만주를 소각하면 자사주 비율은 46%대에서 약 28%로 낮아질 전망이고, 2025년 실적은 매출 2466억원·영업이익 325억원(각각 23.5%, 20.9% 증가)으로 추정됐어요. 주주환원 강화가 이어진 것이 상승 국면 막바지까지 주가를 받친 재료였어요.",
  "https://dealsite.co.kr/articles/156379", "딜사이트")
N("093520", "2024-01-25", "+", "cat", "삼성 PIM 수혜주 부각, 두 달 새 80% 급등",
  "매커스 주가가 2023년 12월 이후 약 80.75% 올라 11월 말 9000원대에서 1만8000원 근처까지 뛰었고, 1월 19일엔 상한가, 22일엔 14% 넘게 올랐어요. 삼성전자·네이버가 공개한 AI 반도체 시제품이 AMD(자일링스) FPGA 플랫폼을 썼고, 매커스가 국내 상장사 중 유일한 AMD자일링스 총판이라는 점이 PIM 수혜 기대로 이어졌어요. 이 테마 편입이 2023년 10월~2024년 2월 상승 국면의 직접적인 동력이었어요.",
  "https://www.newsis.com/view/NISX20240125_0002604169", "뉴시스")
N("094170", "2023-07-24", "-", "cat", "헬스케어 기대에 한 달 5배 급등 뒤 투자위험 지정, 거래재개 후 18% 급락",
  "동운아나텍 주가는 신규 헬스케어 사업 기대감으로 한 달 만에 5배 넘게 올랐고, 한국거래소가 7월 19일 장 마감 후 투자위험종목으로 지정해 20일 하루 거래가 정지됐어요. 거래가 재개된 뒤 24일 장초반 17.95% 급락한 4만450원에 거래됐어요. 장기 상승 국면 안에서 헬스케어(타액 혈당 진단) 테마가 만든 과열과 조정을 보여주는 사건이에요.",
  "https://edaily.co.kr/News/Read?mediaCodeNo=257&newsId=01574406635677800", "이데일리")
N("095340", "2023-07-10", "-", "cat", "SKC 피인수 속 2000억 제3자 유증 희석 우려에 13.6% 급락",
  "ISC 최대주주(헬리오스PE)가 보유 지분 653만여주를 주당 5만5850원에 SKC 측에 넘기기로 하면서, ISC는 SKC·헬리오스PE를 대상으로 2000억원 규모 제3자배정 유상증자(379만여주)도 함께 결정했어요. 주식 가치 희석 우려로 7월 10일 주가는 13.61% 떨어진 4만9500원에 마감했어요. SK그룹 편입 기대와 희석 부담이 엇갈린 이 거래가 2023년 7월 고점 전후 국면의 핵심 사건이었어요.",
  "https://edaily.co.kr/News/Read?mediaCodeNo=257&newsId=02945446635673208", "이데일리")
N("095340", "2025-10-13", "+", "news", "iM증권 목표가 6.4만→10.4만, 3분기 최대 실적 전망",
  "ISC 주가는 2025년 6월 5만원대에서 9월 7만원을 넘어 10월 초 8만원대를 시도했어요. 노르웨이 중앙은행이 지분을 5.03%에서 3.99%로 줄이며 차익을 실현했지만, iM증권은 3분기 매출 695억원·영업이익 201억원(전분기 대비 46% 증가) 최대 실적을 전망하며 목표가를 6만4000원에서 10만4000원으로 62% 올렸어요. AI 인프라향 소켓 수요에 대한 증권가 눈높이 상향이 상승 국면을 이어간 근거였어요.",
  "https://www.edaily.co.kr/News/Read?mediaCodeNo=257&newsId=03772006642332592", "이데일리")
N("094170", "2026-04-30", "+", "cat", "디썰라이프 임상 MARD 8%대 유효성 확인, 연내 허가 목표",
  "동운아나텍이 서울아산병원에서 121명을 대상으로 진행한 타액 혈당 측정기 디썰라이프 임상에서 MARD 8%대 정확도를 확인했다고 4월 30일 발표했어요. 3년 전 서울성모병원 임상(12%대)보다 개선된 수치로, 이상반응은 없었고 5월 식약처 GMP 심사를 거쳐 2026년 안에 품목허가를 받는 것이 목표라고 밝혔어요. 장기 상승을 이끈 헬스케어 기대가 정점에 이른 시점의 발표로, 이후 주가는 2026년 11월까지 -57% 하락 국면으로 돌아섰어요.",
  "https://www.mt.co.kr/thebio/2026/04/30/2026043008543068958", "머니투데이")
N("095610", "2026-06-04", "+", "trend", "코스닥 반도체 장비주 반등에 장중 24% 급등, 12.97만원",
  "테스 주가가 2026년 6월 4일 장중 24.00% 오른 12만9700원에 거래되며 원익IPS 등과 함께 급등했어요. 기사는 회사 고유 재료보다 대형 반도체주에서 코스닥 소부장으로 수급이 돌아온 업종 반등을 원인으로 꼽았고, SK증권은 소부장 실적 추정치가 최근 한 달 상향됐다며 업황 변화는 없다고 봤어요. 이 급등이 2024년 11월부터 이어진 대세 상승의 마지막 구간이었고, 이후 2026년 11월까지 -57% 하락 국면이 시작됐어요.",
  "https://www.mt.co.kr/stock/2026/06/04/2026060409292219832", "머니투데이")
N("094360", "2023-09-27", "+", "cat", "영상특화 AI NPU 개발 완료 소식에 14% 급등",
  "칩스앤미디어가 고화질 영상 처리에 특화된 AI 반도체 NPU 개발을 마쳤다는 소식에 2023년 9월 27일 장초반 14.05% 오른 4만2200원에 거래됐어요. 보도에 따르면 이 NPU는 엔비디아 GPU 대비 전력은 5분의 1, 연산 속도는 약 10배라고 소개됐어요(미검증 주장). AI 반도체 테마에 올라탄 것이 2023년 12월 고점으로 향한 장기 상승 국면 막바지의 핵심 재료였어요.",
  "https://edaily.co.kr/News/Read?mediaCodeNo=257&newsId=01738406635744384", "이데일리")
N("094360", "2025-01-15", "+", "cat", "삼성·구글·퀄컴과 APV 코덱 생태계 참여에 21% 급등",
  "칩스앤미디어가 삼성전자·구글·퀄컴과 함께 차세대 비디오 코덱 APV 생태계 개발에 참여하고 인코더·디코더 하드웨어 IP를 연내 상용화하겠다고 발표했어요. 2025년 1월 15일 주가는 장중 21.11% 오른 1만9560원(고가 1만9920원)까지 올랐어요. 빅테크 협업 소식이 2024년 11월~2025년 1월 반등 국면의 정점을 만든 재료였어요.",
  "https://www.hankyung.com/article/2025011570386", "한국경제")
N("093520", "2026-08-16", "+", "earn", "2분기 영업익 130억(+39.7%), 증권사 추정치 50% 상회",
  "매커스의 2026년 2분기 매출은 668억원(+1.8%), 영업이익은 130억원(+39.7%)으로 영업이익률이 19.5%까지 올랐고, LS증권 추정치를 매출 15.9%, 영업이익 50.2% 웃돌았어요. LS증권은 2026년 영업이익 전망을 338억원에서 375억원으로 높였고, 회사는 4월 자사주 226만1000주를 소각했으며 2025년 주당배당금은 1200원이었어요. 어닝 서프라이즈와 주주환원이 2026년 6월 이후 반등 국면을 뒷받침했어요.",
  "https://view.asiae.co.kr/article/2026081409500823666", "아시아경제")
N("095610", "2026-10-22", "-", "val", "장비주 멀티플 하락에 현대차증권 목표가 23.4만→18만",
  "현대차증권이 반도체 장비 피어들의 평균 밸류에이션 배수 하락을 이유로 테스 목표가를 23만4000원에서 18만원으로 23% 낮췄어요(매수 유지). 3분기 매출은 1252억원(+85.3%), 영업이익은 289억원(+243.0%)으로 실적 자체는 크게 늘었고 내년 영업이익 1479억원(+38.9%)을 전망했어요. 실적보다 업종 멀티플 축소가 주가를 끌어내린 것이 2026년 6월 이후 하락 국면의 성격이었어요.",
  "https://www.mt.co.kr/stock/2026/10/22/2026102208343929716", "머니투데이")
